import { MediaItem, TidalApi, redux } from '@luna/lib'
import {
  normalizeIsrc,
  type CanonicalTrack,
  type CanonicalTrackInput,
  type TrackEnrichPatch,
} from '@everything-jam/protocol'

export interface TrackMeta {
  tidalId: string
  title: string
  artist: string
  album?: string
  coverUrl?: string
  durationMs: number
  isrc?: string
}

export interface ResolvedTidalMatch {
  tidalId: string
  isrc?: string
}

const metaCache = new Map<string, TrackMeta>()
const metaInFlight = new Map<string, Promise<TrackMeta | null>>()
const storeLoadInFlight = new Map<string, Promise<boolean>>()
const foreignResolutionCache = new Map<string, ResolvedTidalMatch | null>()
const foreignResolutionInFlight = new Map<string, Promise<ResolvedTidalMatch | null>>()

const MAX_CACHE_ENTRIES = 500

function setLru<K, V>(map: Map<K, V>, key: K, val: V): void {
  if (!map.has(key) && map.size >= MAX_CACHE_ENTRIES) {
    const oldest = map.keys().next().value
    if (oldest !== undefined) map.delete(oldest)
  }
  map.set(key, val)
}

export function resetMetadataCaches(): void {
  metaCache.clear()
  metaInFlight.clear()
  storeLoadInFlight.clear()
  foreignResolutionCache.clear()
  foreignResolutionInFlight.clear()
}

export function toNativeItemId(trackId: string): redux.ItemId {
  const num = Number(trackId)
  return Number.isInteger(num) && num > 0 ? num : trackId
}

export function isTrackInStore(trackId: string): boolean {
  const state = redux.store.getState() as { content?: { mediaItems?: Record<string, unknown> } }
  if (!state.content?.mediaItems) return true
  return Boolean(state.content.mediaItems[String(trackId)])
}

export function ensureTrackInStore(trackId: string): Promise<boolean> {
  if (isTrackInStore(trackId)) return Promise.resolve(true)
  const existing = storeLoadInFlight.get(trackId)
  if (existing) return existing
  const work = (async () => {
    try {
      const item = await MediaItem.fromId(toNativeItemId(trackId))
      if (item && !metaCache.has(trackId)) {
        resolveTrackMeta(trackId).catch(() => {})
      }
      return isTrackInStore(trackId) || Boolean(item)
    } catch {
      return false
    } finally {
      storeLoadInFlight.delete(trackId)
    }
  })()
  storeLoadInFlight.set(trackId, work)
  return work
}

export async function ensureQueueInStore(trackIds: string[], priorityTrackId?: string | null): Promise<boolean> {
  const uniqueIds = [...new Set(trackIds.filter(Boolean))]
  let fetchedAny = false
  if (priorityTrackId && !isTrackInStore(priorityTrackId)) {
    await ensureTrackInStore(priorityTrackId)
    fetchedAny = true
  }
  const missing = uniqueIds.filter((id) => id !== priorityTrackId && !isTrackInStore(id))
  if (missing.length > 0) {
    fetchedAny = true
    for (let i = 0; i < missing.length; i += 4) {
      const chunk = missing.slice(i, i + 4)
      await Promise.all(chunk.map((id) => ensureTrackInStore(id)))
    }
  }
  return fetchedAny
}

export function getCachedMeta(trackId: string): TrackMeta | undefined {
  return metaCache.get(trackId)
}

export async function resolveTrackMeta(tidalId: string): Promise<TrackMeta | null> {
  const hit = metaCache.get(tidalId)
  if (hit) return hit
  const pending = metaInFlight.get(tidalId)
  if (pending) return pending

  const work = (async () => {
    try {
      const item = await MediaItem.fromId(toNativeItemId(tidalId))
      if (!item) return null
      const tidalItem = item.tidalItem as (redux.Track & { isrc?: string | null }) | undefined
      const rawTitle = await item.title().catch(() => tidalItem?.title ?? '')
      const artistsList = await item.artists().catch(() => [])
      const resolvedArtists = await Promise.all(artistsList)
      const namesFromResolved = resolvedArtists.map((a) => a?.name).filter((n): n is string => Boolean(n))
      const namesFromRaw = (tidalItem?.artists ?? []).map((a) => a.name).filter((n): n is string => Boolean(n))
      const artist = (namesFromResolved.length > 0 ? namesFromResolved : namesFromRaw).join(', ')
      const directAlbum = tidalItem?.album?.title?.trim()
      const albumObj = directAlbum ? undefined : await item.album().catch(() => undefined)
      const albumTitle =
        directAlbum ||
        (albumObj as { tidalAlbum?: { title?: string } } | undefined)?.tidalAlbum?.title?.trim() ||
        (albumObj ? await albumObj.title().catch(() => undefined) : undefined)
      const coverUrl =
        (await item.coverUrl({ res: '320' }).catch(() => undefined)) ??
        (tidalItem?.album?.cover
          ? `https://resources.tidal.com/images/${tidalItem.album.cover.split('-').join('/')}/320x320.jpg`
          : undefined)
      const durationSec =
        typeof item.duration === 'number' && Number.isFinite(item.duration)
          ? item.duration
          : tidalItem?.duration
      const durationMs =
        typeof durationSec === 'number' && Number.isFinite(durationSec) && durationSec > 0
          ? Math.round(durationSec * 1000)
          : 0
      const isrc = normalizeIsrc(tidalItem?.isrc)
      const meta: TrackMeta = {
        tidalId,
        title: rawTitle || tidalItem?.title || `Track ${tidalId}`,
        artist: artist || 'Unknown Artist',
        ...(albumTitle ? { album: albumTitle } : {}),
        ...(coverUrl ? { coverUrl } : {}),
        durationMs,
        ...(isrc ? { isrc } : {}),
      }
      setLru(metaCache, tidalId, meta)
      return meta
    } catch {
      return null
    } finally {
      metaInFlight.delete(tidalId)
    }
  })()

  metaInFlight.set(tidalId, work)
  return work
}

export async function buildCanonicalInputsFromTidalIds(tidalIds: string[]): Promise<CanonicalTrackInput[]> {
  const metas = await Promise.all(tidalIds.map((id) => resolveTrackMeta(id)))
  return tidalIds.map((tidalId, i) => {
    const m = metas[i]
    return {
      uid: `td_${tidalId}_${Date.now().toString(36)}_${i}`,
      title: m?.title ?? `Track ${tidalId}`,
      artist: m?.artist ?? 'TIDAL',
      ...(m?.album ? { album: m.album } : {}),
      durationMs: m?.durationMs ?? 0,
      ...(m?.isrc ? { isrc: m.isrc } : {}),
      ids: { tidal: tidalId },
      ...(m?.coverUrl ? { coverUrl: m.coverUrl } : {}),
    }
  })
}

function cacheKeyForCanonical(track: CanonicalTrack | CanonicalTrackInput): string {
  if (track.isrc) return `isrc:${track.isrc}`
  return `meta:${track.artist.toLowerCase().trim()}|${track.title.toLowerCase().trim()}|${track.durationMs}`
}

export async function resolveCanonicalToTidalId(
  track: CanonicalTrack | CanonicalTrackInput,
): Promise<ResolvedTidalMatch | null> {
  if (track.ids.tidal) {
    return {
      tidalId: track.ids.tidal,
      ...(track.isrc ? { isrc: track.isrc } : {}),
    }
  }

  const key = cacheKeyForCanonical(track)
  if (foreignResolutionCache.has(key)) {
    return foreignResolutionCache.get(key) ?? null
  }
  const inflight = foreignResolutionInFlight.get(key)
  if (inflight) return inflight

  const work = (async (): Promise<ResolvedTidalMatch | null> => {
    try {
      const normalizedIsrc = normalizeIsrc(track.isrc)
      if (normalizedIsrc && typeof MediaItem.fromIsrc === 'function') {
        const byIsrc = await MediaItem.fromIsrc(normalizedIsrc).catch(() => undefined)
        if (byIsrc?.id !== undefined) {
          const hit: ResolvedTidalMatch = { tidalId: String(byIsrc.id), isrc: normalizedIsrc }
          setLru(foreignResolutionCache, key, hit)
          return hit
        }
      }

      const query = `${track.artist} ${track.title}`.trim()
      if (query) {
        const searchResp = await TidalApi.fetch<{
          items?: Array<{ id?: number | string; duration?: number; isrc?: string | null }>
          tracks?: { items?: Array<{ id?: number | string; duration?: number; isrc?: string | null }> }
        }>(
          `https://desktop.tidal.com/v1/search/tracks?query=${encodeURIComponent(query)}&limit=5&${TidalApi.queryArgs()}`,
        ).catch(() => undefined)

        const candidates = searchResp?.items ?? searchResp?.tracks?.items ?? []
        const targetDur = track.durationMs
        const picked =
          (targetDur > 0
            ? candidates.find(
                (c) =>
                  c.id !== undefined &&
                  typeof c.duration === 'number' &&
                  Math.abs(c.duration * 1000 - targetDur) <= 2500,
              )
            : undefined) ?? candidates.find((c) => c.id !== undefined)

        if (picked?.id !== undefined) {
          const foundIsrc = normalizeIsrc(picked.isrc) ?? normalizedIsrc
          const hit: ResolvedTidalMatch = {
            tidalId: String(picked.id),
            ...(foundIsrc ? { isrc: foundIsrc } : {}),
          }
          setLru(foreignResolutionCache, key, hit)
          return hit
        }
      }

      setLru(foreignResolutionCache, key, null)
      return null
    } finally {
      foreignResolutionInFlight.delete(key)
    }
  })()

  foreignResolutionInFlight.set(key, work)
  return work
}

export async function findMissingMetadataUpdates(
  queue: CanonicalTrack[],
  attempted: Set<string>,
): Promise<TrackEnrichPatch[]> {
  const candidates = queue
    .filter((t) => Boolean(t.ids.tidal) && (!t.isrc || !t.coverUrl || t.durationMs === 0) && !attempted.has(t.uid))
    .slice(0, 10)
  if (candidates.length === 0) return []
  for (const t of candidates) attempted.add(t.uid)

  const patches: TrackEnrichPatch[] = []
  await Promise.all(
    candidates.map(async (t) => {
      const tidalId = t.ids.tidal
      if (!tidalId) return
      const meta = await resolveTrackMeta(tidalId)
      if (!meta) return
      const hasNew =
        (meta.isrc && !t.isrc) ||
        (meta.coverUrl && !t.coverUrl) ||
        (meta.durationMs > 0 && t.durationMs === 0)
      if (!hasNew) return
      patches.push({
        uid: t.uid,
        ...(meta.isrc && !t.isrc ? { isrc: meta.isrc } : {}),
        ...(meta.coverUrl && !t.coverUrl ? { coverUrl: meta.coverUrl } : {}),
        ...(meta.durationMs > 0 && t.durationMs === 0 ? { durationMs: meta.durationMs } : {}),
      })
    }),
  )
  return patches
}
