import type { LunaUnload } from '@luna/core'
import { redux } from '@luna/lib'
import { useEffect, useRef, useState, type FC } from 'react'
import { createRoot, type Root } from 'react-dom/client'
import type { SessionClient, SessionState } from '../session/client'
import { IconJam } from './icons'
import type { PopoverController } from './popover'
import { findPlayQueueAside, type QueueHeaderMount } from './queueHeader'

const QUEUE_BTN_SELECTOR =
  '[data-test="play-queue-button"], [data-test="request-queue-button"], [data-test="playqueue-button"], [data-test="toggle-queue"], [data-test*="queue"], [aria-label*="play queue" i], [aria-label*="queue" i], [title*="queue" i]'

function findUtilityContainer(): HTMLElement | null {
  if (typeof document === 'undefined') return null
  const footer = document.querySelector<HTMLElement>('[data-test="footer-player"], #footerPlayer')
  if (!footer) return null

  const explicit =
    footer.querySelector<HTMLElement>('[data-lj-footer-utility]') ??
    footer.querySelector<HTMLElement>('[class*="utilityButtons"]') ??
    footer.querySelector<HTMLElement>('[class*="utilityContainer"]') ??
    footer.querySelector<HTMLElement>('[class*="rightControls"]')
  if (explicit && explicit !== footer) return explicit

  const queueBtn = footer.querySelector<HTMLElement>(QUEUE_BTN_SELECTOR)
  if (queueBtn?.parentElement && queueBtn.parentElement !== footer) {
    return queueBtn.parentElement
  }

  const lyricsBtn = footer.querySelector<HTMLElement>('[data-test="toggle-lyrics"]')
  if (lyricsBtn?.parentElement && lyricsBtn.parentElement !== footer) {
    return lyricsBtn.parentElement
  }

  const sliderOrCompact = footer.querySelector<HTMLElement>(
    '[data-test="select-device"], [class*="_sliderContainer"], [data-test="enter-compact-mode"]',
  )
  if (sliderOrCompact?.parentElement && sliderOrCompact.parentElement !== footer) {
    return sliderOrCompact.parentElement
  }

  const playerContent = footer.querySelector<HTMLElement>('[class*="_playerContent_"]') ?? footer
  if (playerContent.children.length >= 3) {
    return playerContent.lastElementChild as HTMLElement | null
  }
  return null
}

const FooterButtonView: FC<{
  session: SessionClient
  onTrigger: (anchor: HTMLButtonElement) => void
  onButtonRef: (el: HTMLButtonElement | null) => void
}> = ({ session, onTrigger, onButtonRef }) => {
  const [state, setState] = useState<SessionState>(() => session.snapshot())
  const btnRef = useRef<HTMLButtonElement | null>(null)

  useEffect(() => session.subscribe(setState), [session])

  const setRef = (el: HTMLButtonElement | null) => {
    btnRef.current = el
    onButtonRef(el)
  }

  const live = Boolean(state.room) || state.status === 'connecting' || state.status === 'reconnecting'
  const count = state.room?.participants.length ?? 0

  return (
    <button
      ref={setRef}
      type="button"
      className={`lj-footer-btn${live ? ' is-live' : ''}`}
      data-test="lunajam-footer-btn"
      aria-label={live ? `Listen together (${count} in room)` : 'Listen together'}
      title={live ? `Jam (${count})` : 'Listen together'}
      onClick={(ev) => onTrigger(ev.currentTarget)}
    >
      <IconJam />
      {live && <span>{count > 0 ? count : '...'}</span>}
    </button>
  )
}

export class FooterButtonMount {
  private container: HTMLSpanElement | null = null
  private root: Root | null = null
  private observer: MutationObserver | null = null
  private buttonEl: HTMLButtonElement | null = null
  private syncing = false

  constructor(
    unloads: Set<LunaUnload>,
    private session: SessionClient,
    private popover: PopoverController,
    private queueHeader?: QueueHeaderMount,
  ) {
    if (typeof MutationObserver !== 'undefined' && typeof document !== 'undefined' && document.body) {
      this.observer = new MutationObserver((mutations) => {
        if (this.syncing) return
        const relevant = mutations.some(
          (m) => !(m.target as Element | null)?.closest?.('.lj-footer-mount, .lj-footer-host, .lj-popover-layer'),
        )
        if (relevant) this.sync()
      })
      this.observer.observe(document.body, { childList: true, subtree: true })
    }
    unloads.add(() => this.dispose())
    this.sync()
  }

  getAnchorEl(): HTMLElement | null {
    return this.buttonEl ?? this.container
  }

  private cleanupStrays(): void {
    if (typeof document === 'undefined') return
    for (const el of document.querySelectorAll('.lj-footer-mount, .lj-footer-host')) {
      if (el !== this.container) el.remove()
    }
  }

  sync(): void {
    if (this.syncing || typeof document === 'undefined') return
    this.syncing = true
    try {
      this.cleanupStrays()
      if (
        this.container?.isConnected &&
        this.root &&
        this.container.parentElement?.matches('[class*="utilityButtons"], [data-lj-footer-utility], [class*="rightControls"]')
      ) {
        return
      }

      const container = findUtilityContainer()
      if (!container) return

      if (!this.container) {
        this.container = document.createElement('span')
        this.container.className = 'lj-root lj-footer-mount'
        this.container.style.display = 'inline-flex'
        this.container.style.alignItems = 'center'
      }

      if (!this.container.isConnected || this.container.parentElement !== container) {
        const queueToggle = container.querySelector<HTMLElement>(QUEUE_BTN_SELECTOR)
        if (queueToggle && queueToggle.parentElement === container) {
          container.insertBefore(this.container, queueToggle)
        } else {
          container.prepend(this.container)
        }
      }

      if (!this.root) {
        this.root = createRoot(this.container)
        this.root.render(
          <FooterButtonView
            session={this.session}
            onTrigger={(btn) => this.handleTrigger(btn)}
            onButtonRef={(el) => {
              this.buttonEl = el
            }}
          />,
        )
      }
    } finally {
      this.syncing = false
    }
  }

  private handleTrigger(btn: HTMLButtonElement): void {
    if (this.popover.isOpen()) {
      this.popover.close()
      return
    }
    if (!this.queueHeader) {
      this.popover.open(btn)
      return
    }
    const state = this.session.snapshot()
    const active = Boolean(state.room) || state.status === 'connecting' || state.status === 'reconnecting'
    if (!active) {
      this.popover.open(btn)
      return
    }
    if (findPlayQueueAside()) {
      this.queueHeader.pulse()
      this.popover.open(btn)
      return
    }
    try {
      const toggleFn = redux.actions['view/TOGGLE_PLAY_QUEUE_VISIBILITY']
      if (!toggleFn) {
        this.popover.open(btn)
        return
      }
      toggleFn()
    } catch {
      this.popover.open(btn)
      return
    }
    setTimeout(() => {
      this.queueHeader?.sync()
      if (findPlayQueueAside()) {
        this.queueHeader?.pulse()
      } else {
        this.popover.open(btn)
      }
    }, 160)
  }

  private dispose(): void {
    this.observer?.disconnect()
    this.observer = null
    this.root?.unmount()
    this.root = null
    this.container?.remove()
    this.container = null
    this.buttonEl = null
  }
}
