import { ReactiveStore } from '@luna/core'
import { LEGACY_LUNAJAM_URL } from '@everything-jam/protocol'
import { clampManualTrimMs } from '@everything-jam/sync-engine'
import {
  defaultSettings,
  normalizeAudioMode,
  normalizeServerUrl,
  normalizeTrimMs,
  validateDiscordClientId,
  type LunaJamSettings,
} from '../session/settings'

const PEER_RE = /^[A-Za-z0-9_-]{8,64}$/
const FORBIDDEN_KEYS = new Set(['__proto__', 'constructor', 'prototype'])

function isSafeDeviceKey(key: string): boolean {
  return key.length > 0 && key.length <= 128 && !FORBIDDEN_KEYS.has(key)
}

function cleanDeviceTrims(raw: unknown): Record<string, number> {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {}
  const out: Record<string, number> = {}
  for (const [k, v] of Object.entries(raw as Record<string, unknown>)) {
    if (isSafeDeviceKey(k) && typeof v === 'number' && Number.isFinite(v)) {
      out[k] = clampManualTrimMs(v)
    }
  }
  return out
}

function cleanSettings(raw: Record<string, unknown>, base: LunaJamSettings): LunaJamSettings {
  const rawPeer = typeof raw.peerId === 'string' ? raw.peerId.trim() : ''
  return {
    serverUrl: typeof raw.serverUrl === 'string' ? normalizeServerUrl(raw.serverUrl) : base.serverUrl,
    defaultAllowGuestControl:
      typeof raw.defaultAllowGuestControl === 'boolean' ? raw.defaultAllowGuestControl : base.defaultAllowGuestControl,
    defaultAllowGuestAdd:
      typeof raw.defaultAllowGuestAdd === 'boolean' ? raw.defaultAllowGuestAdd : base.defaultAllowGuestAdd,
    defaultGuestAudioMode:
      raw.defaultGuestAudioMode !== undefined
        ? normalizeAudioMode(raw.defaultGuestAudioMode)
        : base.defaultGuestAudioMode,
    manualTrimMs:
      raw.manualTrimMs !== undefined ? normalizeTrimMs(raw.manualTrimMs) : base.manualTrimMs,
    deviceTrims:
      raw.deviceTrims !== undefined ? cleanDeviceTrims(raw.deviceTrims) : base.deviceTrims,
    discordRpcEnabled: typeof raw.discordRpcEnabled === 'boolean' ? raw.discordRpcEnabled : base.discordRpcEnabled,
    discordListenTogether:
      typeof raw.discordListenTogether === 'boolean' ? raw.discordListenTogether : base.discordListenTogether,
    discordShowPaused: typeof raw.discordShowPaused === 'boolean' ? raw.discordShowPaused : base.discordShowPaused,
    discordClientId:
      typeof raw.discordClientId === 'string' ? validateDiscordClientId(raw.discordClientId) : base.discordClientId,
    peerId: PEER_RE.test(rawPeer) ? rawPeer : base.peerId,
  }
}

let current: LunaJamSettings = { ...defaultSettings }
let overlay: Partial<LunaJamSettings> = {}
let persist: ((patch: Partial<LunaJamSettings>) => void) | null = null
const listeners = new Set<(s: LunaJamSettings) => void>()

ReactiveStore.getPluginStorage<LunaJamSettings>('lunajam', defaultSettings)
  .then((store) => {
    persist = (patch) => Object.assign(store, patch)
    const rawStore = store as unknown as Record<string, unknown>
    const merged = cleanSettings(
      overlay as Record<string, unknown>,
      cleanSettings(rawStore, defaultSettings),
    )

    const migrationPatch: Partial<LunaJamSettings> = {}
    if (typeof rawStore.peerId !== 'string' || !PEER_RE.test(rawStore.peerId)) {
      migrationPatch.peerId = merged.peerId
    }
    if (
      typeof rawStore.serverUrl === 'string' &&
      (rawStore.serverUrl.trim().startsWith(LEGACY_LUNAJAM_URL) ||
        rawStore.serverUrl.trim().startsWith('http://lunajam.sn0w13.de'))
    ) {
      migrationPatch.serverUrl = merged.serverUrl
    }
    if ((rawStore.defaultGuestAudioMode as unknown) === 'remote') {
      migrationPatch.defaultGuestAudioMode = 'synced'
    }

    if (Object.keys(migrationPatch).length > 0) persist(migrationPatch)
    if (Object.keys(overlay).length > 0) persist(overlay)

    current = merged
    for (const cb of listeners) cb(current)
  })
  .catch(() => {})

function stripForbiddenTopKeys(patch: Partial<LunaJamSettings>): Partial<LunaJamSettings> {
  const safePatch: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(patch as Record<string, unknown>)) {
    if (!FORBIDDEN_KEYS.has(k)) safePatch[k] = v
  }
  return safePatch as Partial<LunaJamSettings>
}

export const storage = {
  get(): LunaJamSettings {
    return current
  },
  set(patch: Partial<LunaJamSettings>): void {
    const cleanedInput = stripForbiddenTopKeys(patch)
    const next = cleanSettings({ ...current, ...cleanedInput } as Record<string, unknown>, current)
    const safePatch: Partial<LunaJamSettings> =
      'deviceTrims' in cleanedInput ? { ...cleanedInput, deviceTrims: next.deviceTrims } : cleanedInput
    current = next
    overlay = { ...overlay, ...safePatch }
    persist?.(safePatch)
    for (const cb of listeners) cb(current)
  },
  getDeviceTrimMs(deviceId: string): number {
    if (!isSafeDeviceKey(deviceId) || !Object.hasOwn(current.deviceTrims, deviceId)) {
      return current.manualTrimMs
    }
    const dev = current.deviceTrims[deviceId]
    return typeof dev === 'number' ? dev : current.manualTrimMs
  },
  setDeviceTrimMs(deviceId: string, ms: number): void {
    const clean = clampManualTrimMs(ms)
    if (!isSafeDeviceKey(deviceId)) {
      this.set({ manualTrimMs: clean })
      return
    }
    const nextTrims = { ...current.deviceTrims, [deviceId]: clean }
    this.set({ manualTrimMs: clean, deviceTrims: nextTrims })
  },
  onChange(cb: (s: LunaJamSettings) => void): void {
    listeners.add(cb)
  },
  off(cb: (s: LunaJamSettings) => void): void {
    listeners.delete(cb)
  },
}
