import type { LunaUnload } from '@luna/core'
import { MediaItem, PlayState, ipcRenderer, redux } from '@luna/lib'
import {
  buildTrustedHubOrigins,
  parseJoinTarget,
  type CanonicalTrackInput,
} from '@everything-jam/protocol'
import { computeExpectedEnginePosMs } from '@everything-jam/sync-engine'
import type { SessionClient, SessionState } from '../session/client'
import { DEFAULT_DISCORD_CLIENT_ID, normalizeServerUrl } from '../session/settings'
import { localProfile } from '../tidal/identity'
import { resolveTrackMeta } from '../tidal/metadata'
import { storage } from '../tidal/storage'
import { drainLoopbackJoins, setLoopbackAllowedOrigins, startLoopback, stopLoopback } from './loopback.native'
import { rpcDisconnect, rpcSetActivity } from './rpc.native'
import type { RpcButton, WireActivity } from './types'

const PAUSED_ICON_FALLBACK_URL =
  'https://cdn.discordapp.com/app-assets/1130698654987067493/1130747558550061137.png'

export function canAttachDiscordJoinButton(origin: string): boolean {
  try {
    const u = new URL(origin)
    if (u.protocol !== 'https:') return false
    const host = u.hostname.toLowerCase()
    return host !== 'localhost' && host !== '127.0.0.1' && host !== '[::1]'
  } catch {
    return false
  }
}

function fmtField(raw: string | undefined, fallback = 'TIDAL'): string {
  const clean = (raw ?? '').trim()
  if (clean.length === 0) return fallback
  if (clean.length === 1) return `${clean} `
  return clean.length > 128 ? `${clean.slice(0, 125)}...` : clean
}

function composeTrackActivity(opts: {
  clientId: string
  tidalId?: string
  title: string
  artist: string
  album?: string
  coverUrl?: string
  playing: boolean
  durationMs?: number
  elapsedMs: number
  buttons: RpcButton[]
  party?: { id: string; size: [number, number] }
}): WireActivity {
  const isDefaultApp = opts.clientId === DEFAULT_DISCORD_CLIENT_ID
  const largeImage = opts.coverUrl || (isDefaultApp ? 'tidal-logo' : undefined)
  const pauseIcon = isDefaultApp ? 'paused-icon' : PAUSED_ICON_FALLBACK_URL
  const albumText = opts.album?.trim()
  const activity: WireActivity = {
    name: 'TIDAL',
    type: 2,
    status_display_type: 0,
    details: fmtField(opts.title),
    ...(opts.tidalId ? { details_url: `https://tidal.com/browse/track/${opts.tidalId}` } : {}),
    state: fmtField(opts.artist),
    ...(opts.party ? { party: opts.party } : {}),
    buttons: opts.buttons,
    instance: true,
    assets: {
      ...(largeImage ? { large_image: largeImage } : {}),
      ...(albumText ? { large_text: fmtField(albumText) } : {}),
      ...(!opts.playing ? { small_image: pauseIcon, small_text: 'Paused' } : {}),
    },
  }
  if (opts.playing && opts.durationMs && opts.durationMs > 0) {
    const start = Math.round(Date.now() - opts.elapsedMs)
    activity.timestamps = {
      start,
      end: Math.round(start + opts.durationMs),
    }
  }
  return activity
}

export async function buildPresenceActivity(opts: {
  state: SessionState
  listenTogether: boolean
  showPaused: boolean
  clientId: string
  clockNowMs?: number
  onStandbySync?: (info: { trackKey: string; track: CanonicalTrackInput; posMs: number }) => void
}): Promise<WireActivity | null> {
  const { state, listenTogether, showPaused, clientId } = opts
  const room = state.room
  if (room) {
    const activeTrack = room.currentIndex >= 0 ? room.queue[room.currentIndex] : undefined
    const tidalId = activeTrack?.ids.tidal
    const playing = room.anchor.playing
    if (!activeTrack || (!playing && !showPaused)) return null

    const cached =
      tidalId && (!activeTrack.coverUrl || !activeTrack.album) ? await resolveTrackMeta(tidalId) : null
    const title = activeTrack.title || cached?.title || 'Everything-Jam'
    const artist = activeTrack.artist || cached?.artist || 'TIDAL'
    const album = activeTrack.album || cached?.album
    const coverUrl = activeTrack.coverUrl || cached?.coverUrl
    const durationMs = activeTrack.durationMs > 0 ? activeTrack.durationMs : cached?.durationMs

    const elapsedMs = computeExpectedEnginePosMs({
      anchor: room.anchor,
      guestServerNowMs: opts.clockNowMs ?? Date.now(),
      guestOutputLatencyMs: 0,
      mediaOffsetMs: activeTrack.mediaOffsetMs ?? 0,
      trackDurationMs: durationMs ?? 0,
    })

    const buttons: RpcButton[] = []
    if (listenTogether) {
      const origin = normalizeServerUrl(state.serverUrl)
      if (canAttachDiscordJoinButton(origin)) {
        buttons.push({ label: 'Listen Together', url: `${origin}/join/${room.code}` })
      }
    }
    if (tidalId) {
      buttons.push({ label: 'Play on TIDAL', url: `https://tidal.com/browse/track/${tidalId}` })
    }

    return composeTrackActivity({
      clientId,
      tidalId,
      title,
      artist,
      album,
      coverUrl,
      playing,
      durationMs,
      elapsedMs,
      buttons,
      party: {
        id: `lunajam:${room.code}`,
        size: [Math.max(1, room.participants.length), 64],
      },
    })
  }

  const playing = PlayState.playing
  if (!playing && !showPaused) return null

  const item = await MediaItem.fromPlaybackContext().catch(() => undefined)
  if (!item) return null

  const trackId = String(item.id)
  const meta = await resolveTrackMeta(trackId)
  const title = meta?.title || item.tidalItem?.title || 'TIDAL'
  const artist = meta?.artist || 'TIDAL'
  const album = meta?.album || item.tidalItem?.album?.title
  const coverUrl = meta?.coverUrl
  const durationMs =
    meta?.durationMs && meta.durationMs > 0
      ? meta.durationMs
      : typeof item.duration === 'number' && item.duration > 0
        ? Math.round(item.duration * 1000)
        : 0
  const posSec =
    typeof PlayState.currentTime === 'number' && PlayState.currentTime > 0
      ? PlayState.currentTime
      : PlayState.playTime || 0
  const posMs = Math.max(0, Math.round(posSec * 1000))
  const trackKey = `${trackId}:${playing ? 1 : 0}:${Math.floor(posMs / 5000)}`

  const canonical: CanonicalTrackInput = {
    uid: `sb_${trackId}`,
    title,
    artist,
    ...(album ? { album } : {}),
    durationMs,
    ...(meta?.isrc ? { isrc: meta.isrc } : {}),
    ids: { tidal: trackId },
    ...(coverUrl ? { coverUrl } : {}),
  }

  opts.onStandbySync?.({ trackKey, track: canonical, posMs })

  const buttons: RpcButton[] = []
  if (listenTogether && state.standbyId) {
    const origin = normalizeServerUrl(state.serverUrl)
    if (canAttachDiscordJoinButton(origin)) {
      buttons.push({ label: 'Listen Together', url: `${origin}/join/${state.standbyId}` })
    }
  }
  buttons.push({ label: 'Play on TIDAL', url: `https://tidal.com/browse/track/${trackId}` })

  return composeTrackActivity({
    clientId,
    tidalId: trackId,
    title,
    artist,
    album,
    coverUrl,
    playing,
    durationMs,
    elapsedMs: posMs,
    buttons,
  })
}

function activitySignature(clientId: string, a: WireActivity): string {
  return JSON.stringify([
    clientId,
    a.name ?? '',
    a.details ?? '',
    a.state ?? '',
    a.assets?.large_image ?? '',
    a.assets?.large_text ?? '',
    a.assets?.small_image ?? '',
    a.party?.id ?? '',
    a.party?.size ?? null,
    a.buttons ?? [],
  ])
}

export class DiscordPresenceController {
  private debounceTimer: ReturnType<typeof setTimeout> | null = null
  private pollTimer: ReturnType<typeof setInterval> | null = null
  private updating = false
  private rerunRequested = false
  private disposed = false
  private lastStandbyTrackKey = ''
  private lastSentSig = ''
  private lastSentStartMs = 0

  constructor(
    unloads: Set<LunaUnload>,
    private session: SessionClient,
    private hooks: {
      onJoinLink: (code: string, serverUrl?: string) => void
    },
  ) {
    MediaItem.onMediaTransition(unloads, () => this.schedule())
    PlayState.onState(unloads, () => this.schedule())
    redux.intercept('playbackControls/SEEK', unloads, () => {
      setTimeout(() => this.schedule(), 60)
    })

    const unsubSession = this.session.subscribe(() => this.schedule())
    unloads.add(unsubSession)

    const onSettings = () => {
      const nextUrl = normalizeServerUrl(storage.get().serverUrl)
      setLoopbackAllowedOrigins([nextUrl]).catch(() => {})
      const cur = this.session.snapshot()
      if (!cur.room && cur.standbyId && normalizeServerUrl(cur.serverUrl) !== nextUrl) {
        this.lastStandbyTrackKey = ''
        this.session.closeStandby()
      }
      this.schedule()
    }
    storage.onChange(onSettings)
    unloads.add(() => storage.off(onSettings))

    ipcRenderer.onOpenUrl(unloads, (rawUrl: string) => this.handleIncomingUri(rawUrl))

    startLoopback(undefined, [normalizeServerUrl(storage.get().serverUrl)]).catch(() => null)
    this.pollTimer = setInterval(() => {
      drainLoopbackJoins()
        .then((items) => {
          for (const item of items) {
            this.hooks.onJoinLink(item.code, item.serverUrl)
          }
        })
        .catch(() => {})
    }, 900)

    unloads.add(() => this.dispose())
    setTimeout(() => this.schedule(), 250)
  }

  schedule(): void {
    if (this.disposed) return
    if (this.updating) {
      this.rerunRequested = true
      return
    }
    if (this.debounceTimer !== null) clearTimeout(this.debounceTimer)
    this.debounceTimer = setTimeout(() => {
      this.debounceTimer = null
      this.runUpdate().catch(() => {})
    }, 280)
  }

  private handleIncomingUri(rawUrl: string): void {
    const parsed = parseJoinTarget(rawUrl)
    if (!parsed) return
    const trusted = buildTrustedHubOrigins(normalizeServerUrl(storage.get().serverUrl))
    if (parsed.serverUrl !== undefined && !trusted.has(normalizeServerUrl(parsed.serverUrl))) {
      // Preserve raw URI so SessionClient.joinRoom rejects the untrusted server origin.
      this.hooks.onJoinLink(rawUrl)
      return
    }
    this.hooks.onJoinLink(parsed.token, parsed.serverUrl)
  }

  private async runUpdate(): Promise<void> {
    if (this.disposed) return
    this.updating = true
    try {
      const cfg = storage.get()
      const state = this.session.snapshot()

      if (!cfg.discordRpcEnabled) {
        if (!state.room && state.status !== 'connecting' && state.status !== 'reconnecting') {
          this.session.closeStandby()
        }
        this.lastSentSig = ''
        this.lastSentStartMs = 0
        await rpcDisconnect()
        return
      }

      const activePayload = await this.buildActivity(
        state,
        cfg.discordListenTogether,
        cfg.discordShowPaused,
        cfg.discordClientId,
      )
      if (this.disposed) return

      const latest = this.session.snapshot()
      const latestCfg = storage.get()
      if (
        latest.room !== state.room ||
        latest.status !== state.status ||
        latest.standbyId !== state.standbyId ||
        latestCfg.discordRpcEnabled !== cfg.discordRpcEnabled ||
        latestCfg.discordListenTogether !== cfg.discordListenTogether
      ) {
        this.rerunRequested = true
        return
      }

      if (!activePayload) {
        if (!latest.room && latest.status !== 'connecting' && latest.status !== 'reconnecting') {
          this.session.closeStandby()
        }
        this.lastSentSig = ''
        this.lastSentStartMs = 0
        await rpcSetActivity(latestCfg.discordClientId, null)
        return
      }

      const sig = activitySignature(latestCfg.discordClientId, activePayload)
      const startMs = activePayload.timestamps?.start ?? 0
      if (sig === this.lastSentSig && Math.abs(startMs - this.lastSentStartMs) < 2000) {
        return
      }

      const res = await rpcSetActivity(latestCfg.discordClientId, activePayload)
      if (res.connected) {
        this.lastSentSig = sig
        this.lastSentStartMs = startMs
      } else {
        this.lastSentSig = ''
        this.lastSentStartMs = 0
      }
    } finally {
      this.updating = false
      if (this.rerunRequested && !this.disposed) {
        this.rerunRequested = false
        this.schedule()
      }
    }
  }

  private async buildActivity(
    state: SessionState,
    listenTogether: boolean,
    showPaused: boolean,
    clientId: string,
  ): Promise<WireActivity | null> {
    return buildPresenceActivity({
      state,
      listenTogether,
      showPaused,
      clientId,
      clockNowMs: this.session.clock.serverNow(),
      onStandbySync: (info) => {
        const latest = this.session.snapshot()
        const latestCfg = storage.get()
        if (
          this.disposed ||
          latest.room ||
          latest.status === 'connecting' ||
          latest.status === 'reconnecting'
        ) {
          return
        }
        if (latestCfg.discordRpcEnabled && latestCfg.discordListenTogether) {
          const serverUrl = normalizeServerUrl(latestCfg.serverUrl)
          let hasStandby = Boolean(latest.standbyId)
          if (hasStandby && normalizeServerUrl(latest.serverUrl) !== serverUrl) {
            this.lastStandbyTrackKey = ''
            this.session.closeStandby()
            hasStandby = false
          }
          if (!hasStandby) {
            this.lastStandbyTrackKey = info.trackKey
            this.session.openStandby({
              serverUrl,
              profile: localProfile(),
              syncProfile: 'pi-rate',
              track: info.track,
            })
          } else if (info.trackKey !== this.lastStandbyTrackKey) {
            this.lastStandbyTrackKey = info.trackKey
            this.session.updateStandby(info.track)
          }
        } else if (latest.standbyId) {
          this.session.closeStandby()
        }
      },
    })
  }

  private dispose(): void {
    this.disposed = true
    if (this.debounceTimer !== null) clearTimeout(this.debounceTimer)
    if (this.pollTimer !== null) clearInterval(this.pollTimer)
    this.session.closeStandby()
    rpcDisconnect().catch(() => {})
    stopLoopback().catch(() => {})
  }
}
