import { DEFAULT_HUB_URL, LEGACY_LUNAJAM_URL } from './constants.js'
import { isRoomCode, isStandbyToken, normalizeCode } from './validators.js'

export interface ParsedJoinTarget {
  token: string
  serverUrl?: string
}

export interface ParseJoinTargetOptions {
  trustedOrigins?: Iterable<string>
}

function isLoopbackHost(hostname: string): boolean {
  return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '[::1]'
}

export function normalizeHubUrl(raw: string): string {
  const trimmed = raw.trim()
  if (!trimmed) return DEFAULT_HUB_URL
  if (/^(?:javascript|data|vbscript|file|blob):/i.test(trimmed)) return DEFAULT_HUB_URL
  if (trimmed.includes('://') && !/^https?:\/\//i.test(trimmed)) return DEFAULT_HUB_URL
  try {
    const withScheme = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`
    const url = new URL(withScheme)
    if (url.protocol !== 'https:' && url.protocol !== 'http:') return DEFAULT_HUB_URL
    if (url.username || url.password || url.origin === 'null') return DEFAULT_HUB_URL
    if (url.protocol === 'http:' && !isLoopbackHost(url.hostname)) {
      url.protocol = 'https:'
    }
    return url.origin
  } catch {
    return DEFAULT_HUB_URL
  }
}

function sanitizeServerOrigin(raw: string): string | undefined {
  try {
    const url = new URL(raw)
    if (url.username || url.password || url.origin === 'null') return undefined
    if (url.protocol === 'https:') return url.origin
    if (url.protocol === 'http:' && isLoopbackHost(url.hostname)) {
      return url.origin
    }
    return undefined
  } catch {
    return undefined
  }
}

export function buildTrustedHubOrigins(...extra: Array<string | undefined>): Set<string> {
  const trusted = new Set<string>([DEFAULT_HUB_URL, LEGACY_LUNAJAM_URL])
  for (const item of extra) {
    if (!item || !item.trim()) continue
    trusted.add(normalizeHubUrl(item))
  }
  return trusted
}

export function extractTokenFromString(raw: string): string | null {
  const trimmed = raw.trim()
  if (!trimmed) return null
  if (isStandbyToken(trimmed)) return trimmed
  if (isRoomCode(trimmed)) return normalizeCode(trimmed)
  return null
}

export function parseJoinTarget(input: string, opts?: ParseJoinTargetOptions): ParsedJoinTarget | null {
  const trimmed = input.trim()
  if (!trimmed) return null

  const bare = extractTokenFromString(trimmed)
  if (bare) return { token: bare }

  let trustedSet: Set<string> | null = null
  if (opts?.trustedOrigins) {
    trustedSet = new Set<string>()
    for (const origin of opts.trustedOrigins) {
      const clean = sanitizeServerOrigin(origin)
      if (clean) trustedSet.add(clean)
    }
  }

  const filterTrusted = (origin: string | undefined): string | undefined => {
    if (!origin) return undefined
    if (trustedSet && !trustedSet.has(origin)) return undefined
    return origin
  }

  try {
    const url = new URL(trimmed)
    const serverParam = url.searchParams.get('server')

    if (url.protocol === 'https:' || url.protocol === 'http:') {
      const origin = url.username || url.password ? undefined : sanitizeServerOrigin(url.origin)
      const segments = url.pathname.split('/').filter(Boolean)
      const joinIdx = segments.indexOf('join')
      const candidate =
        (joinIdx >= 0 ? segments[joinIdx + 1] : segments[segments.length - 1]) ??
        url.searchParams.get('code') ??
        ''
      const token = extractTokenFromString(candidate)
      if (!token) return null

      if (serverParam !== null) {
        const requested = sanitizeServerOrigin(serverParam)
        if (!requested || !origin || requested !== origin) {
          return { token, serverUrl: undefined }
        }
        const allowed = filterTrusted(requested)
        return { token, serverUrl: allowed }
      }
      const allowed = filterTrusted(origin)
      return { token, ...(allowed ? { serverUrl: allowed } : {}) }
    }

    if (url.protocol === 'everythingjam:' || url.protocol === 'tidaluna:') {
      const rawToken = url.searchParams.get('code') ?? url.pathname.split('/').filter(Boolean).pop() ?? ''
      const token = extractTokenFromString(rawToken)
      if (!token) return null
      const serverUrl = filterTrusted(serverParam ? sanitizeServerOrigin(serverParam) : undefined)
      return { token, ...(serverUrl ? { serverUrl } : {}) }
    }

    return null
  } catch {
    return null
  }
}
