import type { LunaUnload } from '@luna/core'
import { MediaItem, PlayState, redux } from '@luna/lib'
import type {
  AudioMode,
  CanonicalTrack,
  ControlAction,
  PeerTelemetry,
  PlaybackAnchor,
  SyncProfile,
} from '@everything-jam/protocol'
import {
  CONTROLLER_TICK_MS,
  DriftController,
  buildHostAnchor,
  computeExpectedEnginePosMs,
  probeOutputLatencyMs,
  type ClockSync,
} from '@everything-jam/sync-engine'
import { ensureTrackInStore, isTrackInStore, toNativeItemId } from './metadata'
import { storage } from './storage'

export interface DetectedTidalEngine {
  profile: Extract<SyncProfile, 'pi-rate' | 'seek-only'>
  mediaEl: HTMLMediaElement | null
  deviceMode: 'shared' | 'exclusive'
  deviceId: string
}

const HOST_PLAYBACK_ACTIONS: redux.ActionType[] = [
  'playbackControls/PLAY',
  'playbackControls/PAUSE',
  'playbackControls/TOGGLE_PLAYBACK',
]

export function detectTidalEngine(): DetectedTidalEngine {
  const storeState = redux.store.getState() as {
    player?: { activeDeviceMode?: string; activeDeviceId?: string }
    activePlayer?: { activePlayer?: string }
  }
  const deviceId = storeState.player?.activeDeviceId || 'default'
  const isExclusive =
    storeState.player?.activeDeviceMode === 'exclusive' ||
    storeState.activePlayer?.activePlayer === 'EXTERNAL_PLAYER'

  if (isExclusive) {
    return { profile: 'seek-only', mediaEl: null, deviceMode: 'exclusive', deviceId }
  }

  let audioCandidate: HTMLMediaElement | null = null
  if (typeof document !== 'undefined') {
    const candidates = Array.from(document.querySelectorAll<HTMLMediaElement>('audio, video')).filter(
      (el) => !el.muted && !el.loop && (Number.isFinite(el.duration) && el.duration > 0 ? true : !el.paused),
    )
    audioCandidate =
      candidates.find((el) => el.tagName.toLowerCase() === 'audio') ??
      candidates[0] ??
      null
  }

  if (audioCandidate) {
    return { profile: 'pi-rate', mediaEl: audioCandidate, deviceMode: 'shared', deviceId }
  }
  return { profile: 'seek-only', mediaEl: null, deviceMode: 'shared', deviceId }
}

export function readAccuratePositionMs(mediaEl: HTMLMediaElement | null): number {
  if (mediaEl && Number.isFinite(mediaEl.currentTime) && (!mediaEl.paused || mediaEl.currentTime > 0)) {
    return Math.max(0, Math.round(mediaEl.currentTime * 1000))
  }
  const ct = PlayState.currentTime
  if (typeof ct === 'number' && Number.isFinite(ct) && ct > 0) {
    return Math.round(ct * 1000)
  }
  const pt = PlayState.playTime
  if (typeof ct === 'number' && ct === 0 && typeof pt === 'number' && Number.isFinite(pt) && pt > 0.6) {
    return Math.round(pt * 1000)
  }
  return 0
}

export class TidalPlaybackBridge {
  private selfOps = 0
  private drift = new DriftController('pi-rate')
  private syncLoopTimer: ReturnType<typeof setInterval> | null = null
  private hostBeaconTimer: ReturnType<typeof setInterval> | null = null
  private deviceProbeTimer: ReturnType<typeof setTimeout> | null = null
  private hostEpochSeq = 1
  private cachedHwLatencyMs = 0
  private lastTrackUid: string | null = null
  private lastTidalId: string | null = null
  private pendingLoadTrackId: string | null = null
  private pendingLoadAt = 0
  private lastTelemetryAt = 0
  private preResolvedForIndex = -1
  private disposed = false

  constructor(
    unloads: Set<LunaUnload>,
    private hooks: {
      isActive: () => boolean
      getRole: () => 'host' | 'guest' | null
      getAudioMode: () => AudioMode
      canGuestControl: () => boolean
      getClock: () => ClockSync
      getCurrentAnchor: () => PlaybackAnchor | null
      getCurrentQueue: () => CanonicalTrack[]
      getCurrentIndex: () => number
      getTidalIdForTrack: (track: CanonicalTrack | undefined) => string | null
      getQueueIndexByUid: (uid: string) => number
      onHostBroadcastAnchor: (anchor: PlaybackAnchor) => void
      onHostSelectIndex: (index: number) => void
      onGuestControl: (action: ControlAction, posMs?: number) => void
      onPreResolveNext?: (nextIndex: number) => void
      onTelemetry: (telemetry: PeerTelemetry, localDriftMs: number | null) => void
      onRestricted: () => void
    },
  ) {
    void this.refreshHardwareLatency()

    if (typeof navigator !== 'undefined' && navigator.mediaDevices?.addEventListener) {
      const onDeviceChange = () => {
        if (this.deviceProbeTimer) clearTimeout(this.deviceProbeTimer)
        this.deviceProbeTimer = setTimeout(() => {
          void this.refreshHardwareLatency()
        }, 1500)
      }
      navigator.mediaDevices.addEventListener('devicechange', onDeviceChange)
      unloads.add(() => navigator.mediaDevices.removeEventListener('devicechange', onDeviceChange))
    }

    MediaItem.onMediaTransition(unloads, () => {
      if (!this.hooks.isActive()) return
      const role = this.hooks.getRole()
      if (role === 'host') {
        this.hostEpochSeq += 1
        this.emitHostAnchor()
      } else if (role === 'guest') {
        this.pendingLoadTrackId = null
        this.pendingLoadAt = 0
        this.drift.markSeekCompleted(this.hooks.getClock().localNow())
        this.tickGuestSync()
      }
    })

    PlayState.onState(unloads, (state) => {
      if (!this.hooks.isActive()) return
      const role = this.hooks.getRole()
      if (role === 'host') {
        this.hostEpochSeq += 1
        this.emitHostAnchor()
      } else if (role === 'guest' && state === 'PLAYING') {
        this.drift.markSeekCompleted(this.hooks.getClock().localNow())
        queueMicrotask(() => this.tickGuestSync())
      }
    })

    redux.intercept(['playbackControls/SEEK', 'playbackControls/START_AT'], unloads, (seconds) => {
      if (!this.hooks.isActive() || this.selfOps > 0) return
      const role = this.hooks.getRole()
      if (role === 'host') {
        this.hostEpochSeq += 1
        queueMicrotask(() =>
          this.emitHostAnchor(typeof seconds === 'number' ? Math.max(0, Math.round(seconds * 1000)) : undefined),
        )
        return
      }
      if (role === 'guest') {
        if (this.hooks.canGuestControl() && typeof seconds === 'number') {
          this.hooks.onGuestControl('seek', Math.max(0, Math.round(seconds * 1000)))
        } else {
          this.hooks.onRestricted()
        }
        return true
      }
    })

    redux.intercept(
      ['playbackControls/SEEK_BACKWARDS', 'playbackControls/SEEK_FORWARDS', 'playbackControls/STOP'],
      unloads,
      (payload, actionName) => {
        if (!this.hooks.isActive() || this.selfOps > 0) return
        if (this.hooks.getRole() !== 'guest') return
        if (!this.hooks.canGuestControl()) {
          this.hooks.onRestricted()
          return true
        }
        if (actionName === 'playbackControls/STOP') {
          this.hooks.onGuestControl('pause')
          return true
        }
        const delta = typeof payload === 'number' && Number.isFinite(payload) ? payload : 10
        const signed = actionName === 'playbackControls/SEEK_BACKWARDS' ? -Math.abs(delta) : Math.abs(delta)
        const engine = detectTidalEngine()
        const curMs = readAccuratePositionMs(engine.mediaEl)
        this.hooks.onGuestControl('seek', Math.max(0, Math.round(curMs + signed * 1000)))
        return true
      },
    )

    redux.intercept(
      ['playbackControls/PREFILL_MEDIA_PRODUCT_TRANSITION', 'player/PRELOAD_ITEM'],
      unloads,
      (payload) => {
        if (!this.hooks.isActive() || this.selfOps > 0) return
        if (this.hooks.getRole() !== 'guest') return
        if (this.hooks.getAudioMode() === 'speaker') return true
        const p = payload as { productId?: unknown; mediaProduct?: { productId?: unknown } } | null
        const pid = p?.mediaProduct?.productId ?? p?.productId
        const queue = this.hooks.getCurrentQueue()
        const curIdx = this.hooks.getCurrentIndex()
        const expectedTidalId = this.hooks.getTidalIdForTrack(queue[curIdx])
        if (expectedTidalId && pid !== undefined && String(pid) !== expectedTidalId) {
          return true
        }
      },
    )

    redux.intercept(HOST_PLAYBACK_ACTIONS, unloads, (_, actionName) => {
      if (!this.hooks.isActive() || this.selfOps > 0) return
      if (this.hooks.getRole() !== 'guest') return
      if (!this.hooks.canGuestControl()) {
        this.hooks.onRestricted()
        return true
      }
      if (actionName === 'playbackControls/PLAY') this.hooks.onGuestControl('play')
      else if (actionName === 'playbackControls/PAUSE') this.hooks.onGuestControl('pause')
      else this.hooks.onGuestControl(PlayState.playing ? 'pause' : 'play')
      return true
    })

    redux.intercept(['playbackControls/SKIP_NEXT', 'playbackControls/SKIP_PREVIOUS'], unloads, (_, actionName) => {
      if (!this.hooks.isActive() || this.selfOps > 0) return
      const role = this.hooks.getRole()
      if (role === 'host') {
        this.hostEpochSeq += 1
        queueMicrotask(() => this.emitHostAnchor())
        return
      }
      if (role === 'guest') {
        if (!this.hooks.canGuestControl()) {
          this.hooks.onRestricted()
          return true
        }
        this.hooks.onGuestControl(actionName === 'playbackControls/SKIP_NEXT' ? 'next' : 'prev')
        return true
      }
    })

    redux.intercept(['playQueue/MOVE_NEXT', 'playQueue/MOVE_PREVIOUS', 'playQueue/MOVE_TO'], unloads, (_, actionName) => {
      if (!this.hooks.isActive() || this.selfOps > 0) return
      const role = this.hooks.getRole()
      if (role === 'host') {
        this.hostEpochSeq += 1
        queueMicrotask(() => this.emitHostAnchor())
        return
      }
      if (role === 'guest') {
        if (!this.hooks.canGuestControl()) {
          this.hooks.onRestricted()
          return true
        }
        if (actionName === 'playQueue/MOVE_NEXT') this.hooks.onGuestControl('next')
        else if (actionName === 'playQueue/MOVE_PREVIOUS') this.hooks.onGuestControl('prev')
        return true
      }
    })

    this.syncLoopTimer = setInterval(() => {
      if (this.disposed || !this.hooks.isActive()) return
      if (this.hooks.getRole() === 'guest') {
        this.tickGuestSync()
      }
    }, CONTROLLER_TICK_MS)

    this.hostBeaconTimer = setInterval(() => {
      if (!this.disposed && this.hooks.isActive() && this.hooks.getRole() === 'host') {
        this.emitHostAnchor()
      }
    }, 5000)

    unloads.add(() => this.dispose())
  }

  private async refreshHardwareLatency(): Promise<void> {
    const hw = await probeOutputLatencyMs()
    this.cachedHwLatencyMs = hw
  }

  private effectiveOutputLatencyMs(engine: DetectedTidalEngine): number {
    const baseline = engine.deviceMode === 'exclusive' ? 12 : this.cachedHwLatencyMs
    return baseline + storage.getDeviceTrimMs(engine.deviceId)
  }

  readCurrentHostAnchor(overridePosMs?: number, bumpEpoch = false): PlaybackAnchor {
    if (bumpEpoch) this.hostEpochSeq += 1
    const engine = detectTidalEngine()
    const posMs = overridePosMs !== undefined ? Math.max(0, Math.round(overridePosMs)) : readAccuratePositionMs(engine.mediaEl)
    const queue = this.hooks.getCurrentQueue()
    const curIdx = this.hooks.getCurrentIndex()
    const active = curIdx >= 0 ? queue[curIdx] : undefined
    return buildHostAnchor({
      epochSeq: this.hostEpochSeq,
      trackUid: active?.uid ?? null,
      playing: PlayState.playing,
      enginePosMs: posMs,
      hostOutputLatencyMs: this.effectiveOutputLatencyMs(engine),
      hostServerNowMs: this.hooks.getClock().serverNow(),
    })
  }

  emitHostAnchor(overridePosMs?: number): void {
    const anchor = this.readCurrentHostAnchor(overridePosMs)
    this.hooks.onHostBroadcastAnchor(anchor)
  }

  executeHostCommand(action: ControlAction, posMs?: number): void {
    if (this.hooks.getRole() !== 'host') return
    this.ownOp(() => {
      switch (action) {
        case 'play':
          PlayState.play()
          break
        case 'pause':
          PlayState.pause()
          break
        case 'next':
          PlayState.next()
          break
        case 'prev':
          PlayState.previous()
          break
        case 'seek':
          if (typeof posMs === 'number') PlayState.seek(posMs / 1000)
          break
      }
    })
    this.hostEpochSeq += 1
    queueMicrotask(() => this.emitHostAnchor(action === 'seek' ? posMs : undefined))
  }

  onAnchorReceived(): void {
    if (!this.hooks.isActive() || this.hooks.getRole() !== 'guest') return
    this.tickGuestSync()
  }

  tickGuestSync(): void {
    const anchor = this.hooks.getCurrentAnchor()
    const queue = this.hooks.getCurrentQueue()
    const curIdx = this.hooks.getCurrentIndex()
    if (!anchor || curIdx < 0) return

    const activeTrack = queue[curIdx]
    if (!activeTrack) return

    const engine = detectTidalEngine()
    this.drift.setProfile(this.hooks.getAudioMode() === 'speaker' ? 'passive' : engine.profile)

    if (this.hooks.getAudioMode() === 'speaker') {
      this.writeMediaRate(engine.mediaEl, 1)
      if (PlayState.playing) this.ownOp(() => PlayState.pause())
      this.drift.resetState()
      this.lastTrackUid = activeTrack.uid
      this.hooks.onTelemetry(
        {
          driftMs: 0,
          rttMs: Math.round(this.hooks.getClock().rttMs()),
          skewPpm: Math.round(this.hooks.getClock().skewPpm() * 10) / 10,
          outputLatencyMs: this.effectiveOutputLatencyMs(engine),
          buffering: false,
          adIsolated: false,
          updatedAtMs: Date.now(),
        },
        null,
      )
      return
    }

    const targetTidalId = this.hooks.getTidalIdForTrack(activeTrack)
    if (!targetTidalId) {
      if (PlayState.playing) this.ownOp(() => PlayState.pause())
      return
    }

    if (!isTrackInStore(targetTidalId)) {
      ensureTrackInStore(targetTidalId)
        .then((loaded) => {
          if (loaded && !this.disposed) this.tickGuestSync()
        })
        .catch(() => {})
      return
    }

    const pq = PlayState.playQueue
    const rawActual = PlayState.playbackContext?.actualProductId
    const actualTidalId =
      rawActual !== undefined && rawActual !== null && String(rawActual) !== '' ? String(rawActual) : null
    const targetNativeIdx = pq.elements.findIndex(
      (el: redux.PlayQueueElement) => String(el.mediaItemId) === targetTidalId,
    )
    const trackSwitched =
      this.lastTrackUid !== activeTrack.uid || this.lastTidalId !== targetTidalId
    if (trackSwitched) {
      this.lastTrackUid = activeTrack.uid
      this.lastTidalId = targetTidalId
      this.preResolvedForIndex = -1
    }

    const actualMismatch = actualTidalId !== null && actualTidalId !== targetTidalId
    const mustTriggerLoad =
      targetNativeIdx >= 0
        ? pq.currentIndex !== targetNativeIdx || actualMismatch || trackSwitched
        : actualMismatch || trackSwitched

    if (mustTriggerLoad) {
      const nowMono = performance.now()
      const loadInFlight =
        this.pendingLoadTrackId === targetTidalId && nowMono - this.pendingLoadAt < 3000
      if (!loadInFlight) {
        this.pendingLoadTrackId = targetTidalId
        this.pendingLoadAt = nowMono
        if (targetNativeIdx >= 0) {
          this.ownOp(() => PlayState.moveTo(targetNativeIdx))
        } else {
          this.ownOp(() => PlayState.play(toNativeItemId(targetTidalId)))
        }
      }
      const postActual = PlayState.playbackContext?.actualProductId
      const postTrackId =
        postActual !== undefined && postActual !== null && String(postActual) !== ''
          ? String(postActual)
          : null
      if (postTrackId !== null && postTrackId !== targetTidalId) return
    }

    this.pendingLoadTrackId = null

    if (anchor.playing && !anchor.hostAdPaused && !PlayState.playing) {
      this.ownOp(() => PlayState.play())
    } else if ((!anchor.playing || anchor.hostAdPaused) && PlayState.playing) {
      this.ownOp(() => PlayState.pause())
    }

    const rawState = (PlayState as { state?: string }).state
    const buffering = Boolean(anchor.playing && rawState === 'STALLED')
    if (anchor.playing && rawState !== undefined && rawState !== 'PLAYING' && !buffering) {
      return
    }

    const durationMs =
      activeTrack.durationMs > 0
        ? activeTrack.durationMs
        : typeof PlayState.playbackContext?.actualDuration === 'number' &&
            PlayState.playbackContext.actualDuration > 0
          ? Math.round(PlayState.playbackContext.actualDuration * 1000)
          : 0

    const outputLatencyMs = this.effectiveOutputLatencyMs(engine)
    const clock = this.hooks.getClock()
    const expectedMs = computeExpectedEnginePosMs({
      anchor,
      guestServerNowMs: clock.serverNow(),
      guestOutputLatencyMs: outputLatencyMs,
      mediaOffsetMs: activeTrack.mediaOffsetMs ?? 0,
      trackDurationMs: durationMs,
    })
    const actualMs = readAccuratePositionMs(engine.mediaEl)

    const decision = this.drift.step({
      nowMs: clock.localNow(),
      anchor,
      expectedPosMs: expectedMs,
      actualPosMs: actualMs,
      currentRate: engine.mediaEl?.playbackRate ?? 1.0,
      durationMs,
      buffering,
    })

    if (decision.shouldPreResolveNext && this.preResolvedForIndex !== curIdx + 1 && curIdx + 1 < queue.length) {
      this.preResolvedForIndex = curIdx + 1
      this.hooks.onPreResolveNext?.(curIdx + 1)
    }

    if (decision.kind === 'seek') {
      this.writeMediaRate(engine.mediaEl, 1)
      this.ownOp(() => PlayState.seek(decision.seekTargetMs / 1000))
    } else if ((decision.kind === 'rate' || decision.kind === 'hold') && decision.shouldWriteRate) {
      this.writeMediaRate(engine.mediaEl, decision.rate)
    }

    const driftRounded = Math.round(decision.filteredErrorMs * 10) / 10
    const nowWall = Date.now()
    if (nowWall - this.lastTelemetryAt >= 1000) {
      this.lastTelemetryAt = nowWall
      this.hooks.onTelemetry(
        {
          driftMs: driftRounded,
          rttMs: Math.round(clock.rttMs()),
          skewPpm: Math.round(clock.skewPpm() * 10) / 10,
          outputLatencyMs,
          buffering,
          adIsolated: false,
          updatedAtMs: nowWall,
        },
        driftRounded,
      )
    }
  }

  resetSync(): void {
    this.drift.resetState()
    this.lastTrackUid = null
    this.lastTidalId = null
    this.pendingLoadTrackId = null
    this.preResolvedForIndex = -1
    const engine = detectTidalEngine()
    this.writeMediaRate(engine.mediaEl, 1)
  }

  private ownOp(fn: () => void): void {
    this.selfOps++
    try {
      fn()
    } finally {
      this.selfOps--
    }
  }

  private writeMediaRate(media: HTMLMediaElement | null, rate: number): void {
    try {
      if (!media) return
      media.preservesPitch = true
      if (Math.abs(media.playbackRate - rate) > 0.0004) {
        media.playbackRate = rate
      }
    } catch {
      return
    }
  }

  private dispose(): void {
    this.disposed = true
    if (this.syncLoopTimer !== null) clearInterval(this.syncLoopTimer)
    if (this.hostBeaconTimer !== null) clearInterval(this.hostBeaconTimer)
    if (this.deviceProbeTimer !== null) clearTimeout(this.deviceProbeTimer)
    this.syncLoopTimer = null
    this.hostBeaconTimer = null
    this.deviceProbeTimer = null
    this.resetSync()
  }
}
