import type { PlaybackAnchor, SyncProfile } from '@everything-jam/protocol'
import { clamp, median } from './clock.js'

export const CONTROLLER_TICK_MS = 200
export const PRE_RESOLVE_LEAD_MS = 15_000

const PI_KP = 0.125
const PI_KI = 0.0025
const PI_MAX_OFFSET = 0.015
const PI_MAX_INTEGRAL_OFFSET = 0.002
const PI_MAX_INTEGRAL = PI_MAX_INTEGRAL_OFFSET / PI_KI // 0.8
const PI_SLEW_PER_TICK = 0.0025
const PI_DEADBAND_MS = 8
const PI_INTEGRAL_BAND_MS = 25
const PI_SEEK_THRESHOLD_MS = 350
const PI_WRITE_THRESHOLD = 0.0005

const SEEK_ONLY_HOLD_MS = 55
const SEEK_ONLY_HIGH_MS = 250
const SEEK_ONLY_CONFIRM_TICKS = 4
const SEEK_ONLY_MIN_INTERVAL_MS = 4000

const SEEK_EWMA_ALPHA = 0.25
const SEEK_IN_FLIGHT_TIMEOUT_MS = 1200
const POST_SEEK_SETTLE_MS = 600
const MEDIAN_WINDOW_SIZE = 5

export class SeekTracker {
  private ewmaMs: number
  private inFlight = false
  private issuedAtMs = 0
  private lastCompletedAtMs = 0

  constructor(initialLatencyMs = 90) {
    this.ewmaMs = clamp(initialLatencyMs, 0, 600)
  }

  latencyMs(): number {
    return this.ewmaMs
  }

  isBusy(nowMs: number, forceEpochBump: boolean): boolean {
    if (forceEpochBump) return false
    if (this.inFlight && nowMs - this.issuedAtMs < SEEK_IN_FLIGHT_TIMEOUT_MS) {
      return true
    }
    if (this.lastCompletedAtMs > 0 && nowMs - this.lastCompletedAtMs < POST_SEEK_SETTLE_MS) {
      return true
    }
    return false
  }

  canDriftSeek(nowMs: number): boolean {
    if (this.isBusy(nowMs, false)) return false
    if (this.lastCompletedAtMs > 0 && nowMs - this.lastCompletedAtMs < SEEK_ONLY_MIN_INTERVAL_MS) {
      return false
    }
    return true
  }

  markSeekIssued(nowMs: number): void {
    this.inFlight = true
    this.issuedAtMs = nowMs
  }

  markSeekCompleted(nowMs: number): void {
    if (this.inFlight && this.issuedAtMs > 0) {
      const measured = clamp(nowMs - this.issuedAtMs, 0, 600)
      this.ewmaMs = (1 - SEEK_EWMA_ALPHA) * this.ewmaMs + SEEK_EWMA_ALPHA * measured
    }
    this.inFlight = false
    this.lastCompletedAtMs = nowMs
  }

  predictiveTargetMs(expectedPosMs: number, playing: boolean, durationMs = 0): number {
    const lead = playing ? this.ewmaMs : 0
    const raw = expectedPosMs + lead
    return durationMs > 0 ? clamp(raw, 0, durationMs) : Math.max(0, raw)
  }

  reset(initialLatencyMs?: number): void {
    if (initialLatencyMs !== undefined) {
      this.ewmaMs = clamp(initialLatencyMs, 0, 600)
    }
    this.inFlight = false
    this.issuedAtMs = 0
    this.lastCompletedAtMs = 0
  }
}

export interface ControllerStepInput {
  nowMs: number
  anchor: PlaybackAnchor
  expectedPosMs: number
  actualPosMs: number
  currentRate: number
  durationMs?: number
  buffering?: boolean
  adIsolated?: boolean
}

export type ControllerAction =
  | {
      kind: 'hold'
      filteredErrorMs: number
      rawErrorMs: number
      rate: number
      shouldWriteRate: boolean
      shouldPreResolveNext: boolean
    }
  | {
      kind: 'pause'
      filteredErrorMs: number
      rawErrorMs: number
      rate: number
      shouldPreResolveNext: boolean
    }
  | {
      kind: 'hold-ad'
      filteredErrorMs: number
      rawErrorMs: number
      shouldPreResolveNext: boolean
    }
  | {
      kind: 'rate'
      filteredErrorMs: number
      rawErrorMs: number
      rate: number
      shouldWriteRate: boolean
      shouldPreResolveNext: boolean
    }
  | {
      kind: 'seek'
      filteredErrorMs: number
      rawErrorMs: number
      seekTargetMs: number
      rate: number
      reason: 'epoch' | 'large-drift' | 'sustained-drift' | 'ad-exit'
      shouldPreResolveNext: boolean
    }

export class DriftController {
  private profile: SyncProfile
  private readonly seekTracker: SeekTracker
  private errorHistory: number[] = []
  private integral = 0
  private lastCmdRate = 1.0
  private lastEpochSeq = -1
  private sustainedDriftTicks = 0
  private wasAdIsolated = false
  private pendingAdExitSeek = false
  private pendingEpochSeek = false

  constructor(profile: SyncProfile = 'pi-rate', initialSeekLatencyMs?: number) {
    this.profile = profile
    const fallbackLatency = profile === 'seek-only' ? 140 : 90
    this.seekTracker = new SeekTracker(initialSeekLatencyMs ?? fallbackLatency)
  }

  getProfile(): SyncProfile {
    return this.profile
  }

  setProfile(profile: SyncProfile): void {
    if (this.profile === profile) return
    this.profile = profile
    this.resetState(profile === 'seek-only' ? 140 : 90)
  }

  resetState(seekLatencyMs?: number): void {
    this.errorHistory = []
    this.integral = 0
    this.lastCmdRate = 1.0
    this.lastEpochSeq = -1
    this.sustainedDriftTicks = 0
    this.wasAdIsolated = false
    this.pendingAdExitSeek = false
    this.pendingEpochSeek = false
    this.seekTracker.reset(seekLatencyMs)
  }

  markSeekCompleted(nowMs: number): void {
    this.seekTracker.markSeekCompleted(nowMs)
    this.errorHistory = []
    this.sustainedDriftTicks = 0
    this.lastCmdRate = 1.0
  }

  seekLatencyMs(): number {
    return this.seekTracker.latencyMs()
  }

  step(input: ControllerStepInput): ControllerAction {
    const durationMs = input.durationMs ?? 0
    const rawErrorMs = input.expectedPosMs - input.actualPosMs
    const shouldPreResolveNext = durationMs > 0 && durationMs - input.actualPosMs <= PRE_RESOLVE_LEAD_MS

    if (input.adIsolated) {
      this.wasAdIsolated = true
      this.pendingAdExitSeek = false
      this.errorHistory = []
      this.sustainedDriftTicks = 0
      return {
        kind: 'hold-ad',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        shouldPreResolveNext,
      }
    }

    if (this.wasAdIsolated) {
      this.wasAdIsolated = false
      this.pendingAdExitSeek = true
    }

    const epochChanged =
      this.lastEpochSeq !== -1 && input.anchor.epochSeq !== this.lastEpochSeq
    if (this.lastEpochSeq === -1 || epochChanged) {
      this.lastEpochSeq = input.anchor.epochSeq
      if (epochChanged) {
        this.pendingEpochSeek = true
      }
      this.errorHistory = []
      this.sustainedDriftTicks = 0
      this.integral = 0
    }

    if (!input.anchor.playing || input.anchor.hostAdPaused) {
      this.lastCmdRate = 1.0
      return {
        kind: 'pause',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        rate: 1.0,
        shouldPreResolveNext,
      }
    }

    if (this.profile === 'passive') {
      return {
        kind: 'hold',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        rate: 1.0,
        shouldWriteRate: false,
        shouldPreResolveNext,
      }
    }

    if (input.buffering) {
      return {
        kind: 'hold',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        rate: 1.0,
        shouldWriteRate: Math.abs(input.currentRate - 1.0) >= PI_WRITE_THRESHOLD,
        shouldPreResolveNext,
      }
    }

    if (this.pendingAdExitSeek) {
      this.pendingAdExitSeek = false
      this.pendingEpochSeek = false
      const target = this.seekTracker.predictiveTargetMs(input.expectedPosMs, true, durationMs)
      this.seekTracker.markSeekIssued(input.nowMs)
      this.errorHistory = []
      this.lastCmdRate = 1.0
      return {
        kind: 'seek',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        seekTargetMs: target,
        rate: 1.0,
        reason: 'ad-exit',
        shouldPreResolveNext,
      }
    }

    if (this.pendingEpochSeek) {
      this.pendingEpochSeek = false
      if (Math.abs(rawErrorMs) > 60) {
        const target = this.seekTracker.predictiveTargetMs(input.expectedPosMs, true, durationMs)
        this.seekTracker.markSeekIssued(input.nowMs)
        this.errorHistory = []
        this.lastCmdRate = 1.0
        return {
          kind: 'seek',
          filteredErrorMs: rawErrorMs,
          rawErrorMs,
          seekTargetMs: target,
          rate: 1.0,
          reason: 'epoch',
          shouldPreResolveNext,
        }
      }
    }

    if (this.seekTracker.isBusy(input.nowMs, false)) {
      return {
        kind: 'hold',
        filteredErrorMs: rawErrorMs,
        rawErrorMs,
        rate: 1.0,
        shouldWriteRate: Math.abs(input.currentRate - 1.0) >= PI_WRITE_THRESHOLD,
        shouldPreResolveNext,
      }
    }

    this.errorHistory.push(rawErrorMs)
    if (this.errorHistory.length > MEDIAN_WINDOW_SIZE) {
      this.errorHistory.shift()
    }
    const filteredErrorMs = median(this.errorHistory)
    const absErr = Math.abs(filteredErrorMs)

    if (this.profile === 'seek-only') {
      return this.stepSeekOnly(input, filteredErrorMs, rawErrorMs, absErr, durationMs, shouldPreResolveNext)
    }

    return this.stepPiRate(input, filteredErrorMs, rawErrorMs, absErr, durationMs, shouldPreResolveNext)
  }

  private stepSeekOnly(
    input: ControllerStepInput,
    filteredErrorMs: number,
    rawErrorMs: number,
    absErr: number,
    durationMs: number,
    shouldPreResolveNext: boolean,
  ): ControllerAction {
    if (absErr > SEEK_ONLY_HIGH_MS) {
      const target = this.seekTracker.predictiveTargetMs(input.expectedPosMs, true, durationMs)
      this.seekTracker.markSeekIssued(input.nowMs)
      this.errorHistory = []
      this.sustainedDriftTicks = 0
      return {
        kind: 'seek',
        filteredErrorMs,
        rawErrorMs,
        seekTargetMs: target,
        rate: 1.0,
        reason: 'large-drift',
        shouldPreResolveNext,
      }
    }

    if (absErr >= SEEK_ONLY_HOLD_MS) {
      this.sustainedDriftTicks += 1
      if (this.sustainedDriftTicks >= SEEK_ONLY_CONFIRM_TICKS && this.seekTracker.canDriftSeek(input.nowMs)) {
        const target = this.seekTracker.predictiveTargetMs(input.expectedPosMs, true, durationMs)
        this.seekTracker.markSeekIssued(input.nowMs)
        this.errorHistory = []
        this.sustainedDriftTicks = 0
        return {
          kind: 'seek',
          filteredErrorMs,
          rawErrorMs,
          seekTargetMs: target,
          rate: 1.0,
          reason: 'sustained-drift',
          shouldPreResolveNext,
        }
      }
    } else {
      this.sustainedDriftTicks = 0
    }

    return {
      kind: 'hold',
      filteredErrorMs,
      rawErrorMs,
      rate: 1.0,
      shouldWriteRate: Math.abs(input.currentRate - 1.0) >= PI_WRITE_THRESHOLD,
      shouldPreResolveNext,
    }
  }

  private stepPiRate(
    input: ControllerStepInput,
    filteredErrorMs: number,
    rawErrorMs: number,
    absErr: number,
    durationMs: number,
    shouldPreResolveNext: boolean,
  ): ControllerAction {
    if (absErr > PI_SEEK_THRESHOLD_MS) {
      const target = this.seekTracker.predictiveTargetMs(input.expectedPosMs, true, durationMs)
      this.seekTracker.markSeekIssued(input.nowMs)
      this.errorHistory = []
      this.lastCmdRate = 1.0
      return {
        kind: 'seek',
        filteredErrorMs,
        rawErrorMs,
        seekTargetMs: target,
        rate: 1.0,
        reason: 'large-drift',
        shouldPreResolveNext,
      }
    }

    const dtSec = CONTROLLER_TICK_MS / 1000
    const epsSec = filteredErrorMs / 1000

    if (absErr < PI_DEADBAND_MS) {
      const targetRate = clamp(1.0 + PI_KI * this.integral, 1.0 - PI_MAX_OFFSET, 1.0 + PI_MAX_OFFSET)
      const slewed = clamp(
        targetRate,
        this.lastCmdRate - PI_SLEW_PER_TICK,
        this.lastCmdRate + PI_SLEW_PER_TICK,
      )
      this.lastCmdRate = slewed
      return {
        kind: 'hold',
        filteredErrorMs,
        rawErrorMs,
        rate: slewed,
        shouldWriteRate: Math.abs(slewed - input.currentRate) >= PI_WRITE_THRESHOLD,
        shouldPreResolveNext,
      }
    }

    const rawOffset = PI_KP * epsSec + PI_KI * this.integral
    const isSaturated = Math.abs(rawOffset) >= PI_MAX_OFFSET

    if (!isSaturated && absErr <= PI_INTEGRAL_BAND_MS) {
      this.integral = clamp(this.integral + epsSec * dtSec, -PI_MAX_INTEGRAL, PI_MAX_INTEGRAL)
    }

    const nextOffset = clamp(PI_KP * epsSec + PI_KI * this.integral, -PI_MAX_OFFSET, PI_MAX_OFFSET)
    const targetRate = 1.0 + nextOffset
    const slewed = clamp(
      targetRate,
      this.lastCmdRate - PI_SLEW_PER_TICK,
      this.lastCmdRate + PI_SLEW_PER_TICK,
    )
    this.lastCmdRate = slewed

    return {
      kind: 'rate',
      filteredErrorMs,
      rawErrorMs,
      rate: slewed,
      shouldWriteRate: Math.abs(slewed - input.currentRate) >= PI_WRITE_THRESHOLD,
      shouldPreResolveNext,
    }
  }
}
