export interface ClockSample {
  seq: number
  t0: number
  t1: number
  t2: number
  t3: number
  rtt: number
  theta: number
}

export interface ClockSyncOptions {
  nowWall?: () => number
  nowMono?: () => number
  windowSize?: number
  sampleTtlMs?: number
}

export const BURST_INTERVALS_MS = [0, 120, 160, 220, 350, 550] as const
export const STEADY_PING_INTERVAL_MS = 5_000
const MAX_SKEW = 5e-4 // +-500 ppm
const SLEEP_DRIFT_THRESHOLD_MS = 2_000
const SKEW_MIN_SPAN_MS = 30_000
const SKEW_MIN_SAMPLES = 6
const MAX_PENDING_PINGS = 32
const PENDING_PING_TTL_MS = 10_000

export function median(values: readonly number[]): number {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  if (sorted.length % 2 === 1) return sorted[mid]!
  return (sorted[mid - 1]! + sorted[mid]!) / 2
}

export function clamp(val: number, min: number, max: number): number {
  if (val < min) return min
  if (val > max) return max
  return val
}

export class ClockSync {
  private readonly nowWall: () => number
  private readonly nowMono: () => number
  private readonly windowSize: number
  private readonly sampleTtlMs: number

  private anchorWallOffset = 0
  private samples: ClockSample[] = []
  private burstIdx = 0
  private seedOffset = 0
  private hasSeed = false
  private hasEstimate = false

  private anchorT3 = 0
  private anchorTheta = 0
  private slope = 0
  private currentRtt = 0
  private sleepResetCount = 0
  private nextSeq = 0
  private pendingPings = new Map<number, number>()
  private trackingPings = false

  constructor(opts: ClockSyncOptions = {}) {
    this.nowWall = opts.nowWall ?? (() => Date.now())
    this.nowMono = opts.nowMono ?? (() => performance.now())
    this.windowSize = opts.windowSize ?? 16
    this.sampleTtlMs = opts.sampleTtlMs ?? 90_000
    this.anchorWallOffset = this.nowWall() - this.nowMono()
  }

  localNow(): number {
    const mono = this.nowMono()
    const wall = this.nowWall()
    const est = this.anchorWallOffset + mono
    if (Math.abs(wall - est) > SLEEP_DRIFT_THRESHOLD_MS) {
      this.handleSuspendRecovery(wall, mono)
      return wall
    }
    return est
  }

  private handleSuspendRecovery(wall: number, mono: number): void {
    this.anchorWallOffset = wall - mono
    this.samples = []
    this.burstIdx = 0
    this.hasEstimate = false
    this.hasSeed = false
    this.seedOffset = 0
    this.anchorTheta = 0
    this.anchorT3 = wall
    this.slope = 0
    this.currentRtt = 0
    this.sleepResetCount += 1
    this.pendingPings.clear()
  }

  private prunePendingPings(nowMs: number): void {
    for (const [seq, sentAt] of this.pendingPings) {
      if (
        !Number.isFinite(sentAt) ||
        nowMs - sentAt > PENDING_PING_TTL_MS ||
        sentAt > nowMs + SLEEP_DRIFT_THRESHOLD_MS
      ) {
        this.pendingPings.delete(seq)
      }
    }
    while (this.pendingPings.size > MAX_PENDING_PINGS) {
      const oldest = this.pendingPings.keys().next().value
      if (oldest === undefined) break
      this.pendingPings.delete(oldest)
    }
  }

  nextPing(t0 = this.localNow()): { seq: number; t0: number } {
    this.trackingPings = true
    this.nextSeq += 1
    const seq = this.nextSeq
    this.pendingPings.set(seq, t0)
    this.prunePendingPings(t0)
    return { seq, t0 }
  }

  registerPing(seq: number, t0 = this.localNow()): void {
    if (!Number.isInteger(seq) || seq < 0 || !Number.isFinite(t0)) return
    this.trackingPings = true
    this.nextSeq = Math.max(this.nextSeq, seq)
    this.pendingPings.set(seq, t0)
    this.prunePendingPings(t0)
  }

  seedFromWelcome(serverTs: number, localMs = this.localNow()): void {
    if (this.hasEstimate || this.samples.length > 0) return
    if (!Number.isFinite(serverTs) || serverTs <= 0) return
    this.seedOffset = serverTs - localMs
    this.hasSeed = true
  }

  ingestPong(
    pong: { seq: number; t0: number; t1: number; t2: number },
    t3 = this.localNow(),
  ): ClockSample | null {
    const { seq, t0, t1, t2 } = pong
    if (
      !Number.isInteger(seq) ||
      seq < 0 ||
      !Number.isFinite(t0) ||
      !Number.isFinite(t1) ||
      !Number.isFinite(t2) ||
      !Number.isFinite(t3) ||
      t3 < t0 ||
      t2 < t1
    ) {
      return null
    }

    if (this.trackingPings) {
      this.prunePendingPings(t3)
      const expectedT0 = this.pendingPings.get(seq)
      if (expectedT0 === undefined || Math.abs(t0 - expectedT0) > 0.001) {
        return null
      }
      this.pendingPings.delete(seq)
    }

    const rtt = t3 - t0 - (t2 - t1)
    if (!Number.isFinite(rtt) || rtt < 0 || rtt > 10_000) return null

    const theta = (t1 - t0 + (t2 - t3)) / 2
    const sample: ClockSample = { seq, t0, t1, t2, t3, rtt, theta }

    const cutoffTime = t3 - this.sampleTtlMs
    this.samples = this.samples.filter((s) => s.t3 >= cutoffTime)
    this.samples.push(sample)
    if (this.samples.length > this.windowSize) {
      this.samples = this.samples.slice(this.samples.length - this.windowSize)
    }

    this.recompute(t3)
    return sample
  }

  private recompute(refT3: number): void {
    if (this.samples.length === 0) {
      this.hasEstimate = false
      return
    }

    const rtts = this.samples.map((s) => s.rtt)
    const rttMin = Math.min(...rtts)
    const medRtt = median(rtts)
    const madRtt = median(rtts.map((r) => Math.abs(r - medRtt)))
    const maxAcceptableRtt = rttMin + Math.max(15, 1.5 * madRtt)

    let selected = this.samples.filter((s) => s.rtt <= maxAcceptableRtt)
    const minKeep = Math.min(this.samples.length, Math.max(3, Math.ceil(this.samples.length / 2)))
    if (selected.length < minKeep) {
      selected = [...this.samples].sort((a, b) => a.rtt - b.rtt).slice(0, minKeep)
    }

    this.currentRtt = median(selected.map((s) => s.rtt))
    this.hasEstimate = true

    const t3Values = selected.map((s) => s.t3)
    const spanMs = Math.max(...t3Values) - Math.min(...t3Values)

    if (spanMs >= SKEW_MIN_SPAN_MS && selected.length >= SKEW_MIN_SAMPLES) {
      const meanT = selected.reduce((acc, s) => acc + s.t3, 0) / selected.length
      const meanTheta = selected.reduce((acc, s) => acc + s.theta, 0) / selected.length
      let num = 0
      let den = 0
      for (const s of selected) {
        const dt = s.t3 - meanT
        num += dt * (s.theta - meanTheta)
        den += dt * dt
      }
      this.slope = den > 0 ? clamp(num / den, -MAX_SKEW, MAX_SKEW) : 0
      this.anchorT3 = meanT
      this.anchorTheta = meanTheta
      return
    }

    this.slope = 0
    this.anchorT3 = refT3
    this.anchorTheta = median(selected.map((s) => s.theta))
  }

  offsetMs(localMs = this.localNow()): number {
    if (!this.hasEstimate) {
      return this.hasSeed ? this.seedOffset : 0
    }
    return this.anchorTheta + this.slope * (localMs - this.anchorT3)
  }

  serverNow(localMs = this.localNow()): number {
    return localMs + this.offsetMs(localMs)
  }

  rttMs(): number {
    return this.currentRtt
  }

  skewPpm(): number {
    return this.slope * 1_000_000
  }

  isLocked(): boolean {
    return this.hasEstimate
  }

  sampleCount(): number {
    return this.samples.length
  }

  suspendResetCount(): number {
    return this.sleepResetCount
  }

  nextPingDelayMs(): number {
    if (this.burstIdx < BURST_INTERVALS_MS.length) {
      const delay = BURST_INTERVALS_MS[this.burstIdx]!
      this.burstIdx += 1
      return delay
    }
    return STEADY_PING_INTERVAL_MS
  }

  resetBurst(): void {
    this.burstIdx = 0
    this.pendingPings.clear()
  }
}
