import {
  DEFAULT_HUB_URL,
  LEGACY_LUNAJAM_URL,
  decodeServerMsg,
  encodeMsg,
  isRoomCode,
  isStandbyToken,
  normalizeCode,
  normalizeIsrc,
  parseJoinTarget,
  type AudioMode,
  type CanonicalTrackInput,
  type ClientMsg,
  type ControlAction,
  type Participant,
  type ParticipantProfile,
  type PeerTelemetry,
  type PlaybackAnchor,
  type QueuePatchOp,
  type RoomState,
  type RoomSummary,
  type ServerMsg,
  type SyncProfile,
  type TrackEnrichPatch,
} from '@everything-jam/protocol'
import { ClockSync } from '@everything-jam/sync-engine'
import { normalizeServerUrl, wsUrlFromServer } from './settings'

export interface WsLike {
  readonly readyState: number
  send(data: string): void
  close(code?: number): void
  onopen: ((ev: unknown) => void) | null
  onmessage: ((ev: { data: unknown }) => void) | null
  onclose: ((ev?: { code?: number; reason?: string }) => void) | null
  onerror: ((ev: unknown) => void) | null
}

export type SessionStatus = 'idle' | 'connecting' | 'reconnecting' | 'connected' | 'ended'
export type EndReason = Extract<ServerMsg, { t: 'room.ended' }>['reason']

export interface SessionState {
  status: SessionStatus
  role: 'host' | 'guest' | null
  cid: string | null
  standbyId: string | null
  standbyCode: string | null
  room: RoomState | null
  audioMode: AudioMode
  syncProfile: SyncProfile
  endReason: EndReason | null
  error: string | null
  serverUrl: string
  localDriftMs: number | null
}

export type AnchorHandler = (anchor: PlaybackAnchor) => void
export type CommandHandler = (action: ControlAction, posMs: number | undefined, fromCid: string) => void
export type PromotedHandler = (room: RoomState) => void

type PendingIntent =
  | {
      kind: 'create'
      profile: ParticipantProfile
      syncProfile: SyncProfile
      audioMode: AudioMode
      allowGuestControl: boolean
      allowGuestAdd: boolean
      queue: CanonicalTrackInput[]
      currentIndex: number
      anchor: PlaybackAnchor
      code?: string
      hostToken?: string
    }
  | {
      kind: 'join'
      code: string
      profile: ParticipantProfile
      syncProfile: SyncProfile
      audioMode: AudioMode
    }
  | {
      kind: 'standby'
      profile: ParticipantProfile
      syncProfile: SyncProfile
      track: CanonicalTrackInput | null
    }

const WS_OPEN = 1
const TERMINAL_ROOM_ERRORS = new Set([
  'room_not_found',
  'room_banned',
  'room_full',
  'server_full',
  'room_limit_reached',
  'rooms_per_conn',
  'too_many_rooms',
  'host_replaced',
])

function applyQueuePatch(room: RoomState, rev: number, op: QueuePatchOp): RoomState {
  const queue = [...room.queue]
  let currentIndex = op.currentIndex
  switch (op.kind) {
    case 'add': {
      if (op.insert === 'next' && room.currentIndex >= 0 && room.currentIndex < queue.length) {
        queue.splice(room.currentIndex + 1, 0, ...op.tracks)
      } else {
        queue.push(...op.tracks)
      }
      break
    }
    case 'remove': {
      const idx = queue.findIndex((t) => t.uid === op.uid)
      if (idx >= 0) queue.splice(idx, 1)
      break
    }
    case 'move': {
      if (
        op.fromIndex >= 0 &&
        op.fromIndex < queue.length &&
        op.toIndex >= 0 &&
        op.toIndex < queue.length
      ) {
        const [item] = queue.splice(op.fromIndex, 1)
        if (item) queue.splice(op.toIndex, 0, item)
      }
      break
    }
    case 'clear': {
      queue.length = 0
      currentIndex = -1
      break
    }
    case 'select':
      break
    case 'replace':
      return { ...room, queue: op.queue, queueRev: rev, currentIndex }
  }
  return { ...room, queue, queueRev: rev, currentIndex }
}

export class SessionClient {
  readonly clock = new ClockSync()
  private ws: WsLike | null = null
  private wsUrl = ''
  private pingTimer: ReturnType<typeof setTimeout> | null = null
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private reconnectAttempt = 0
  private hostToken: string | null = null
  private intent: PendingIntent | null = null
  private joinSeq = 0
  private disposed = false

  private stateListeners = new Set<(state: SessionState) => void>()
  private anchorListeners = new Set<AnchorHandler>()
  private commandListeners = new Set<CommandHandler>()
  private promotedListeners = new Set<PromotedHandler>()

  private state: SessionState = {
    status: 'idle',
    role: null,
    cid: null,
    standbyId: null,
    standbyCode: null,
    room: null,
    audioMode: 'synced',
    syncProfile: 'pi-rate',
    endReason: null,
    error: null,
    serverUrl: DEFAULT_HUB_URL,
    localDriftMs: null,
  }

  constructor(
    private wsFactory: (url: string) => WsLike = (url) => new WebSocket(url) as unknown as WsLike,
    private fetchFn: typeof fetch = (...args) => globalThis.fetch(...args),
  ) {}

  snapshot(): SessionState {
    return this.state
  }

  subscribe(cb: (state: SessionState) => void): () => void {
    this.stateListeners.add(cb)
    return () => this.stateListeners.delete(cb)
  }

  onAnchor(cb: AnchorHandler): () => void {
    this.anchorListeners.add(cb)
    return () => this.anchorListeners.delete(cb)
  }

  onCommand(cb: CommandHandler): () => void {
    this.commandListeners.add(cb)
    return () => this.commandListeners.delete(cb)
  }

  onPromoted(cb: PromotedHandler): () => void {
    this.promotedListeners.add(cb)
    return () => this.promotedListeners.delete(cb)
  }

  setLocalDriftMs(ms: number | null): void {
    if (this.state.localDriftMs === ms) return
    this.updateState({ localDriftMs: ms })
  }

  openStandby(opts: {
    serverUrl: string
    profile: ParticipantProfile
    syncProfile: SyncProfile
    track: CanonicalTrackInput | null
  }): void {
    if (
      this.disposed ||
      this.state.room ||
      this.state.status === 'connecting' ||
      this.state.status === 'reconnecting' ||
      this.intent?.kind === 'create' ||
      this.intent?.kind === 'join'
    ) {
      return
    }
    this.joinSeq += 1
    const serverUrl = normalizeServerUrl(opts.serverUrl)
    this.intent = {
      kind: 'standby',
      profile: opts.profile,
      syncProfile: opts.syncProfile,
      track: opts.track,
    }
    this.updateState({ serverUrl, error: null, endReason: null })
    if (this.ws && this.ws.readyState === WS_OPEN && this.wsUrl === wsUrlFromServer(serverUrl)) {
      this.send({
        v: 3,
        t: 'standby.open',
        profile: opts.profile,
        syncProfile: opts.syncProfile,
        track: opts.track,
      })
      return
    }
    this.openSocket(serverUrl)
  }

  updateStandby(track: CanonicalTrackInput | null): void {
    if (this.intent?.kind === 'standby') {
      this.intent.track = track
    }
    if (!this.state.standbyId) return
    this.send({ v: 3, t: 'standby.update', track })
  }

  closeStandby(): void {
    if (this.intent?.kind === 'standby') {
      this.intent = null
    }
    if (this.state.standbyId) {
      this.send({ v: 3, t: 'standby.close' })
      this.updateState({ standbyId: null, standbyCode: null })
    }
    if (!this.state.room && !this.intent) {
      this.disconnectSocket()
    }
  }

  createRoom(opts: {
    serverUrl: string
    profile: ParticipantProfile
    syncProfile: SyncProfile
    allowGuestControl: boolean
    allowGuestAdd?: boolean
    queue: CanonicalTrackInput[]
    currentIndex: number
    anchor: PlaybackAnchor
  }): void {
    if (this.disposed) return
    this.joinSeq += 1
    this.clearReconnect()
    this.hostToken = null
    const serverUrl = normalizeServerUrl(opts.serverUrl)
    this.intent = {
      kind: 'create',
      profile: opts.profile,
      syncProfile: opts.syncProfile,
      audioMode: 'synced',
      allowGuestControl: opts.allowGuestControl,
      allowGuestAdd: opts.allowGuestAdd ?? true,
      queue: opts.queue,
      currentIndex: opts.currentIndex,
      anchor: opts.anchor,
    }
    this.updateState({
      status: 'connecting',
      error: null,
      endReason: null,
      serverUrl,
      syncProfile: opts.syncProfile,
      audioMode: 'synced',
    })
    if (this.ws && this.ws.readyState === WS_OPEN && this.wsUrl === wsUrlFromServer(serverUrl)) {
      this.flushIntent()
      return
    }
    this.openSocket(serverUrl)
  }

  async joinRoom(opts: {
    input: string
    serverUrl: string
    profile: ParticipantProfile
    syncProfile: SyncProfile
    audioMode: AudioMode
  }): Promise<boolean> {
    if (this.disposed) return false
    const parsed = parseJoinTarget(opts.input)
    if (!parsed) {
      this.updateState({ error: 'Invalid Jam code or invite link' })
      return false
    }

    const configuredUrl = normalizeServerUrl(opts.serverUrl)
    const trustedRawOrigins = new Set<string>([
      DEFAULT_HUB_URL,
      LEGACY_LUNAJAM_URL,
      configuredUrl,
    ])
    if (parsed.serverUrl !== undefined && !trustedRawOrigins.has(parsed.serverUrl)) {
      this.updateState({
        status: 'idle',
        error: 'Invite link points to an untrusted Jam server. Change Relay URL in Settings first.',
      })
      return false
    }

    const serverUrl = parsed.serverUrl ? normalizeServerUrl(parsed.serverUrl) : configuredUrl
    const seq = ++this.joinSeq
    this.clearReconnect()
    this.hostToken = null
    let code = parsed.token

    if (isStandbyToken(code)) {
      this.updateState({ status: 'connecting', error: null, endReason: null, serverUrl })
      try {
        const res = await this.fetchFn(`${serverUrl}/api/rooms/${encodeURIComponent(code)}`)
        if (this.disposed || seq !== this.joinSeq) return false
        if (!res.ok) {
          this.updateState({ status: 'idle', error: 'Jam is no longer active' })
          return false
        }
        const summary = (await res.json()) as Partial<RoomSummary>
        if (this.disposed || seq !== this.joinSeq) return false
        if (typeof summary.code !== 'string' || !isRoomCode(summary.code)) {
          this.updateState({ status: 'idle', error: 'Invalid Jam room response' })
          return false
        }
        code = normalizeCode(summary.code)
      } catch {
        if (this.disposed || seq !== this.joinSeq) return false
        this.updateState({ status: 'idle', error: 'Could not reach Jam relay server' })
        return false
      }
    }

    if (this.disposed || seq !== this.joinSeq) return false

    this.intent = {
      kind: 'join',
      code,
      profile: opts.profile,
      syncProfile: opts.syncProfile,
      audioMode: opts.audioMode,
    }
    this.updateState({
      status: 'connecting',
      error: null,
      endReason: null,
      serverUrl,
      audioMode: opts.audioMode,
      syncProfile: opts.syncProfile,
    })

    if (this.ws && this.ws.readyState === WS_OPEN && this.wsUrl === wsUrlFromServer(serverUrl)) {
      this.flushIntent()
      return true
    }
    this.openSocket(serverUrl)
    return true
  }

  leaveRoom(): void {
    this.joinSeq += 1
    this.clearReconnect()
    this.intent = null
    this.hostToken = null
    this.send({ v: 3, t: 'room.leave' })
    this.disconnectSocket()
    this.updateState({
      status: 'idle',
      role: null,
      room: null,
      error: null,
      endReason: null,
      localDriftMs: null,
    })
  }

  endRoom(): void {
    this.joinSeq += 1
    this.clearReconnect()
    this.intent = null
    this.hostToken = null
    this.send({ v: 3, t: 'room.end' })
    this.disconnectSocket()
    this.updateState({
      status: 'idle',
      role: null,
      room: null,
      error: null,
      endReason: null,
      localDriftMs: null,
    })
  }

  kick(targetCid: string): void {
    this.send({ v: 3, t: 'room.kick', targetCid })
  }

  kickAll(): void {
    this.send({ v: 3, t: 'room.kickAll' })
  }

  setPermissions(patch: { allowGuestControl?: boolean; allowGuestAdd?: boolean }): void {
    if (patch.allowGuestControl === undefined && patch.allowGuestAdd === undefined) return
    this.send({ v: 3, t: 'room.permissions', ...patch })
  }

  setMemberCanAdd(targetCid: string, canAddTracks: boolean): void {
    this.send({ v: 3, t: 'room.memberPermission', targetCid, canAddTracks })
  }

  setAudioMode(audioMode: AudioMode, syncProfile?: SyncProfile): void {
    this.updateState({
      audioMode,
      ...(syncProfile ? { syncProfile } : {}),
    })
    if (this.intent?.kind === 'join') {
      this.intent.audioMode = audioMode
      if (syncProfile) this.intent.syncProfile = syncProfile
    }
    if (this.state.room) {
      this.send({ v: 3, t: 'room.mode', audioMode, ...(syncProfile ? { syncProfile } : {}) })
    }
  }

  updateProfile(profile: ParticipantProfile): void {
    if (this.intent) this.intent.profile = profile
    if (this.state.room) {
      this.send({
        v: 3,
        t: 'profile.update',
        name: profile.name,
        avatarUrl: profile.avatarUrl,
        platform: profile.platform,
        ...(profile.profileUrl ? { profileUrl: profile.profileUrl } : {}),
      })
    }
  }

  sendAnchor(anchor: PlaybackAnchor): void {
    if (this.state.role !== 'host' || !this.state.room) return
    if (this.intent?.kind === 'create') {
      this.intent.anchor = anchor
    }
    this.updateState({
      room: { ...this.state.room, anchor },
    })
    this.send({ v: 3, t: 'anchor.update', anchor })
  }

  sendControl(action: ControlAction, posMs?: number): void {
    this.send({
      v: 3,
      t: 'playback.control',
      action,
      ...(posMs !== undefined ? { posMs } : {}),
    })
  }

  addTracks(tracks: CanonicalTrackInput[], insert: 'next' | 'last'): void {
    if (tracks.length === 0) return
    this.send({ v: 3, t: 'queue.add', insert, tracks })
  }

  removeTrack(uid: string): void {
    this.send({ v: 3, t: 'queue.remove', uid })
  }

  moveTrack(fromIndex: number, toIndex: number): void {
    this.send({ v: 3, t: 'queue.move', fromIndex, toIndex })
  }

  selectQueueIndex(index: number): void {
    this.send({ v: 3, t: 'queue.select', index })
  }

  replaceQueue(queue: CanonicalTrackInput[], currentIndex: number): void {
    if (this.intent?.kind === 'create') {
      this.intent.queue = queue
      this.intent.currentIndex = currentIndex
    }
    this.send({ v: 3, t: 'queue.replace', queue, currentIndex })
  }

  enrichTrack(patch: TrackEnrichPatch): void {
    if (!this.state.room) return
    const hasChanges =
      Boolean(normalizeIsrc(patch.isrc)) ||
      (patch.ids !== undefined && Object.keys(patch.ids).length > 0) ||
      (patch.durationMs !== undefined && patch.durationMs > 0) ||
      Boolean(patch.coverUrl) ||
      Boolean(patch.previewUrl) ||
      patch.mediaOffsetMs !== undefined
    if (hasChanges) {
      this.send({ v: 3, t: 'track.enrich', patch })
    }
  }

  sendTelemetry(telemetry: PeerTelemetry): void {
    if (!this.state.room) return
    this.send({ v: 3, t: 'peer.telemetry', telemetry })
  }

  dispose(): void {
    this.disposed = true
    this.joinSeq += 1
    this.clearReconnect()
    this.intent = null
    this.disconnectSocket()
    this.stateListeners.clear()
    this.anchorListeners.clear()
    this.commandListeners.clear()
    this.promotedListeners.clear()
  }

  private openSocket(serverUrl: string): void {
    this.disconnectSocket()
    const wsUrl = wsUrlFromServer(serverUrl)
    this.wsUrl = wsUrl

    try {
      const ws = this.wsFactory(wsUrl)
      this.ws = ws

      ws.onopen = () => {
        if (this.ws !== ws) return
        this.reconnectAttempt = 0
        this.clock.resetBurst()
        this.scheduleNextPing()
        this.flushIntent()
      }

      ws.onmessage = (ev) => {
        if (this.ws !== ws) return
        const raw = typeof ev.data === 'string' ? ev.data : String(ev.data ?? '')
        const msg = decodeServerMsg(raw)
        if (!msg) return
        this.handleServerMsg(msg)
      }

      ws.onerror = () => {
        if (this.ws !== ws) return
        if (this.state.status === 'connecting' && !this.state.error) {
          this.updateState({ error: 'Unable to reach Jam relay' })
        }
      }

      ws.onclose = () => {
        if (this.ws !== ws) return
        this.stopPingTimer()
        this.ws = null
        if (this.disposed) return
        if (this.state.room || (this.intent && this.intent.kind !== 'standby')) {
          this.updateState({ status: 'reconnecting', standbyId: null, standbyCode: null })
          this.scheduleReconnect()
        } else if (this.intent?.kind === 'standby') {
          this.updateState({ standbyId: null, standbyCode: null })
          this.scheduleReconnect()
        } else {
          this.updateState({ status: 'idle', cid: null })
        }
      }
    } catch {
      this.updateState({ status: 'idle', error: 'Could not open WebSocket connection' })
    }
  }

  private flushIntent(): void {
    const intent = this.intent
    if (!intent) return
    switch (intent.kind) {
      case 'standby':
        this.send({
          v: 3,
          t: 'standby.open',
          profile: intent.profile,
          syncProfile: intent.syncProfile,
          track: intent.track,
        })
        return
      case 'create': {
        this.send({
          v: 3,
          t: 'room.create',
          profile: intent.profile,
          syncProfile: intent.syncProfile,
          audioMode: intent.audioMode,
          allowGuestControl: intent.allowGuestControl,
          allowGuestAdd: intent.allowGuestAdd,
          queue: intent.queue,
          currentIndex: intent.currentIndex,
          anchor: intent.anchor,
          ...(intent.code && intent.hostToken ? { code: intent.code, hostToken: intent.hostToken } : {}),
        })
        return
      }
      case 'join':
        this.send({
          v: 3,
          t: 'room.join',
          code: intent.code,
          profile: intent.profile,
          syncProfile: intent.syncProfile,
          audioMode: intent.audioMode,
        })
        return
    }
  }

  private handleServerMsg(msg: ServerMsg): void {
    switch (msg.t) {
      case 'welcome':
        this.clock.seedFromWelcome(msg.serverTs)
        this.updateState({ cid: msg.cid })
        return
      case 'clock.pong':
        this.clock.ingestPong(msg)
        return
      case 'standby.ready':
        this.updateState({ standbyId: msg.standbyId, standbyCode: msg.code })
        return
      case 'standby.promoted': {
        this.hostToken = msg.hostToken
        this.intent = {
          kind: 'create',
          profile: msg.state.participants[0] ?? {
            cid: this.state.cid ?? '',
            name: 'Host',
            avatarUrl: null,
            platform: 'tidal',
          },
          syncProfile: this.state.syncProfile,
          audioMode: 'synced',
          allowGuestControl: msg.state.allowGuestControl,
          allowGuestAdd: msg.state.allowGuestAdd,
          queue: msg.state.queue,
          currentIndex: msg.state.currentIndex,
          anchor: msg.state.anchor,
          code: msg.state.code,
          hostToken: msg.hostToken,
        }
        this.updateState({
          status: 'connected',
          role: 'host',
          room: msg.state,
          standbyId: null,
          standbyCode: null,
          audioMode: 'synced',
          error: null,
        })
        for (const cb of this.promotedListeners) cb(msg.state)
        return
      }
      case 'room.joined':
        if (msg.hostToken) this.hostToken = msg.hostToken
        if (msg.role === 'host' && this.intent?.kind === 'create') {
          this.intent.code = msg.state.code
          this.intent.hostToken = this.hostToken ?? undefined
          this.intent.queue = msg.state.queue
          this.intent.currentIndex = msg.state.currentIndex
          this.intent.anchor = msg.state.anchor
        }
        this.updateState({
          status: 'connected',
          role: msg.role,
          room: msg.state,
          standbyId: null,
          standbyCode: null,
          error: null,
          endReason: null,
        })
        return
      case 'room.state':
        if (this.intent?.kind === 'create') {
          this.intent.queue = msg.state.queue
          this.intent.currentIndex = msg.state.currentIndex
          this.intent.anchor = msg.state.anchor
          this.intent.allowGuestControl = msg.state.allowGuestControl
          this.intent.allowGuestAdd = msg.state.allowGuestAdd
        }
        this.updateState({ room: msg.state })
        return
      case 'anchor.broadcast': {
        if (!this.state.room) return
        if (this.intent?.kind === 'create') this.intent.anchor = msg.anchor
        this.updateState({ room: { ...this.state.room, anchor: msg.anchor } })
        for (const cb of this.anchorListeners) cb(msg.anchor)
        return
      }
      case 'queue.patch': {
        if (!this.state.room) return
        const nextRoom = applyQueuePatch(this.state.room, msg.rev, msg.op)
        if (this.intent?.kind === 'create') {
          this.intent.queue = nextRoom.queue
          this.intent.currentIndex = nextRoom.currentIndex
        }
        this.updateState({ room: nextRoom })
        return
      }
      case 'track.updated': {
        if (!this.state.room) return
        const nextQueue = this.state.room.queue.map((t) => (t.uid === msg.track.uid ? msg.track : t))
        const nextRoom = { ...this.state.room, queue: nextQueue }
        this.updateState({ room: nextRoom })
        return
      }
      case 'peer.telemetry.broadcast': {
        if (!this.state.room) return
        const nextParticipants: Participant[] = this.state.room.participants.map((p) =>
          p.cid === msg.cid ? { ...p, telemetry: msg.telemetry } : p,
        )
        this.updateState({ room: { ...this.state.room, participants: nextParticipants } })
        return
      }
      case 'command.execute':
        for (const cb of this.commandListeners) cb(msg.action, msg.posMs, msg.fromCid)
        return
      case 'room.ended':
        this.clearReconnect()
        this.intent = null
        this.hostToken = null
        this.disconnectSocket()
        this.updateState({
          status: 'ended',
          role: null,
          room: null,
          endReason: msg.reason,
          localDriftMs: null,
        })
        return
      case 'error': {
        const terminal =
          TERMINAL_ROOM_ERRORS.has(msg.code) ||
          !this.state.room ||
          this.state.status !== 'connected'
        if (!terminal) {
          this.updateState({ error: msg.message })
          return
        }
        this.clearReconnect()
        this.intent = null
        this.hostToken = null
        this.disconnectSocket()
        this.updateState({
          status: 'idle',
          role: null,
          room: null,
          error: msg.message,
          endReason: msg.code === 'room_banned' ? 'banned' : null,
          localDriftMs: null,
        })
        return
      }
    }
  }

  private send(msg: ClientMsg): boolean {
    if (!this.ws || this.ws.readyState !== WS_OPEN) return false
    try {
      this.ws.send(encodeMsg(msg))
      return true
    } catch {
      return false
    }
  }

  private scheduleNextPing(): void {
    this.stopPingTimer()
    const delay = this.clock.nextPingDelayMs()
    this.pingTimer = setTimeout(() => {
      this.pingTimer = null
      if (!this.ws || this.ws.readyState !== WS_OPEN) return
      const ping = this.clock.nextPing()
      if (this.send({ v: 3, t: 'clock.ping', seq: ping.seq, t0: ping.t0 })) {
        this.scheduleNextPing()
      }
    }, delay)
  }

  private stopPingTimer(): void {
    if (this.pingTimer !== null) {
      clearTimeout(this.pingTimer)
      this.pingTimer = null
    }
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer !== null || this.disposed) return
    const delay = Math.min(8000, 600 * Math.pow(2, this.reconnectAttempt))
    this.reconnectAttempt += 1
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null
      if (!this.disposed && this.intent) {
        this.openSocket(this.state.serverUrl)
      }
    }, delay)
  }

  private clearReconnect(): void {
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    this.reconnectAttempt = 0
  }

  private disconnectSocket(): void {
    this.stopPingTimer()
    const ws = this.ws
    this.ws = null
    if (ws) {
      ws.onopen = null
      ws.onmessage = null
      ws.onclose = null
      ws.onerror = null
      try {
        ws.close()
      } catch {
        // Ignore close errors
      }
    }
  }

  private updateState(patch: Partial<SessionState>): void {
    this.state = { ...this.state, ...patch }
    for (const cb of this.stateListeners) cb(this.state)
  }
}
