import {
  COVER_DOMAINS,
  MAX_BATCH_ADD,
  MAX_PARTICIPANTS,
  MAX_QUEUE_TRACKS,
  PREVIEW_AUDIO_DOMAINS,
  PROTOCOL_VERSION,
  ROOM_CODE_ALPHABET,
  ROOM_CODE_LENGTH,
} from './constants.js'
import type {
  AudioMode,
  CanonicalTrack,
  CanonicalTrackInput,
  ClientMsg,
  ControlAction,
  Participant,
  ParticipantProfile,
  PeerTelemetry,
  PlatformId,
  PlatformKey,
  PlatformTrackIds,
  PlaybackAnchor,
  QueuePatchOp,
  RoomState,
  ServerMsg,
  SyncProfile,
  TrackEnrichPatch,
} from './types.js'

const ROOM_CHAR_SET = new Set(ROOM_CODE_ALPHABET)
const ISRC_RE = /^[A-Z]{2}[A-Z0-9]{3}\d{7}$/
const STANDBY_RE = /^s_[A-Za-z0-9_-]{8,32}$/

function isDisallowedChar(code: number): boolean {
  return (
    code <= 0x1f ||
    (code >= 0x7f && code <= 0x9f) ||
    code === 0x200e ||
    code === 0x200f ||
    (code >= 0x202a && code <= 0x202e) ||
    (code >= 0x2066 && code <= 0x2069)
  )
}

const VALID_PLATFORMS = new Set<PlatformId>([
  'tidal',
  'spotify',
  'youtube',
  'soundcloud',
  'appleMusic',
  'deezer',
  'web',
])

const VALID_PLATFORM_KEYS: readonly PlatformKey[] = [
  'tidal',
  'spotify',
  'youtube',
  'soundcloud',
  'appleMusic',
  'deezer',
]

const VALID_SYNC_PROFILES = new Set<SyncProfile>(['pi-rate', 'seek-only', 'passive'])
const VALID_AUDIO_MODES = new Set<AudioMode>(['synced', 'speaker'])
const VALID_ACTIONS = new Set<ControlAction>(['play', 'pause', 'next', 'prev', 'seek'])
const VALID_END_REASONS = new Set<Extract<ServerMsg, { t: 'room.ended' }>['reason']>([
  'host_ended',
  'host_left',
  'banned',
  'expired',
  'kicked_all',
])

export function stripBidiAndControl(raw: string): string {
  let filtered = ''
  for (const ch of raw) {
    const code = ch.codePointAt(0) ?? 0
    if (!isDisallowedChar(code)) filtered += ch
  }
  return filtered.replace(/\s+/g, ' ').trim()
}

export function cleanStr(raw: unknown, maxLen: number): string | null {
  if (typeof raw !== 'string') return null
  const cleaned = stripBidiAndControl(raw)
  if (!cleaned) return null
  return cleaned.length > maxLen ? cleaned.slice(0, maxLen) : cleaned
}

function finiteNum(raw: unknown, min: number, max: number): number | null {
  if (typeof raw !== 'number' || !Number.isFinite(raw)) return null
  if (raw < min || raw > max) return null
  return raw
}

function finiteInt(raw: unknown, min: number, max: number): number | null {
  const n = finiteNum(raw, min, max)
  if (n === null || !Number.isInteger(n)) return null
  return n
}

export function normalizeCode(raw: string): string {
  return raw.toUpperCase().replace(/[^A-Z0-9]/g, '')
}

export function isRoomCode(raw: string): boolean {
  const code = normalizeCode(raw)
  if (code.length !== ROOM_CODE_LENGTH) return false
  for (const ch of code) {
    if (!ROOM_CHAR_SET.has(ch)) return false
  }
  return true
}

export function formatCode(raw: string): string {
  const code = normalizeCode(raw)
  if (code.length !== ROOM_CODE_LENGTH) return raw
  return `${code.slice(0, 4)}-${code.slice(4)}`
}

export function isStandbyToken(raw: string): boolean {
  return STANDBY_RE.test(raw.trim())
}

export function normalizeIsrc(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined
  const compact = raw.toUpperCase().replace(/[^A-Z0-9]/g, '')
  return ISRC_RE.test(compact) ? compact : undefined
}

export function sanitizeHttpsUrl(raw: unknown, allowDomains?: readonly string[]): string | undefined {
  if (typeof raw !== 'string') return undefined
  const trimmed = raw.trim()
  if (!trimmed || trimmed.length > 1024) return undefined
  try {
    const url = new URL(trimmed)
    if (url.protocol !== 'https:' || url.username || url.password) return undefined
    const host = url.hostname.toLowerCase()
    if (!allowDomains) return url.toString()
    for (const domain of allowDomains) {
      if (host === domain || host.endsWith(`.${domain}`)) {
        return url.toString()
      }
    }
    return undefined
  } catch {
    return undefined
  }
}

export function normalizePlatformIds(raw: unknown): PlatformTrackIds {
  if (!raw || typeof raw !== 'object') return {}
  const rec = raw as Record<string, unknown>
  const out: PlatformTrackIds = {}
  for (const key of VALID_PLATFORM_KEYS) {
    const val = cleanStr(rec[key], 256)
    if (val) out[key] = val
  }
  return out
}

function parseProfile(raw: unknown): ParticipantProfile | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  const name = cleanStr(obj.name, 48)
  if (!name) return null
  const cid = cleanStr(obj.cid, 64) ?? ''
  const platform =
    typeof obj.platform === 'string' && VALID_PLATFORMS.has(obj.platform as PlatformId)
      ? (obj.platform as PlatformId)
      : 'web'
  const avatarUrl =
    obj.avatarUrl === null || obj.avatarUrl === undefined
      ? null
      : (sanitizeHttpsUrl(obj.avatarUrl, COVER_DOMAINS) ?? null)
  const profileUrl = sanitizeHttpsUrl(obj.profileUrl)
  return {
    cid,
    name,
    avatarUrl,
    platform,
    ...(profileUrl ? { profileUrl } : {}),
  }
}

function parseTelemetry(raw: unknown): PeerTelemetry | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  const driftMs = finiteNum(obj.driftMs, -60_000, 60_000)
  const rttMs = finiteNum(obj.rttMs, 0, 30_000)
  const skewPpm = finiteNum(obj.skewPpm, -2000, 2000)
  const outputLatencyMs = finiteNum(obj.outputLatencyMs, -2000, 2000)
  const updatedAtMs = finiteNum(obj.updatedAtMs, 0, 1e14)
  if (
    driftMs === null ||
    rttMs === null ||
    skewPpm === null ||
    outputLatencyMs === null ||
    updatedAtMs === null ||
    typeof obj.buffering !== 'boolean' ||
    typeof obj.adIsolated !== 'boolean'
  ) {
    return null
  }
  return {
    driftMs,
    rttMs,
    skewPpm,
    outputLatencyMs,
    buffering: obj.buffering,
    adIsolated: obj.adIsolated,
    updatedAtMs,
  }
}

function parseParticipant(raw: unknown): Participant | null {
  const base = parseProfile(raw)
  if (!base) return null
  const obj = raw as Record<string, unknown>
  if (obj.role !== 'host' && obj.role !== 'guest') return null
  if (typeof obj.audioMode !== 'string' || !VALID_AUDIO_MODES.has(obj.audioMode as AudioMode)) {
    return null
  }
  if (typeof obj.syncProfile !== 'string' || !VALID_SYNC_PROFILES.has(obj.syncProfile as SyncProfile)) {
    return null
  }
  if (typeof obj.canAddTracks !== 'boolean') return null
  const telemetry = obj.telemetry !== undefined ? parseTelemetry(obj.telemetry) : undefined
  return {
    ...base,
    role: obj.role,
    audioMode: obj.audioMode as AudioMode,
    syncProfile: obj.syncProfile as SyncProfile,
    canAddTracks: obj.canAddTracks,
    ...(telemetry ? { telemetry } : {}),
  }
}

function parseTrackInput(raw: unknown): CanonicalTrackInput | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  const uid = cleanStr(obj.uid, 64)
  const title = cleanStr(obj.title, 180)
  const artist = cleanStr(obj.artist, 180)
  const durationMs = finiteInt(obj.durationMs, 0, 86_400_000)
  if (!uid || !title || !artist || durationMs === null) return null

  const album = cleanStr(obj.album, 180) ?? undefined
  const isrc = normalizeIsrc(obj.isrc)
  const ids = normalizePlatformIds(obj.ids)
  const coverUrl = sanitizeHttpsUrl(obj.coverUrl, COVER_DOMAINS)
  const previewUrl = sanitizeHttpsUrl(obj.previewUrl, PREVIEW_AUDIO_DOMAINS)
  const mediaOffsetMs =
    obj.mediaOffsetMs !== undefined ? (finiteInt(obj.mediaOffsetMs, -300_000, 300_000) ?? undefined) : undefined

  return {
    uid,
    title,
    artist,
    ...(album ? { album } : {}),
    durationMs,
    ...(isrc ? { isrc } : {}),
    ids,
    ...(coverUrl ? { coverUrl } : {}),
    ...(previewUrl ? { previewUrl } : {}),
    ...(mediaOffsetMs !== undefined ? { mediaOffsetMs } : {}),
  }
}

function parseTrack(raw: unknown): CanonicalTrack | null {
  const input = parseTrackInput(raw)
  if (!input) return null
  const addedBy = parseProfile((raw as Record<string, unknown>).addedBy)
  if (!addedBy) return null
  return { ...input, addedBy }
}

function parseAnchor(raw: unknown): PlaybackAnchor | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  const epochSeq = finiteInt(obj.epochSeq, 0, 1e12)
  const anchorPosMs = finiteNum(obj.anchorPosMs, 0, 86_400_000)
  const anchorServerMs = finiteNum(obj.anchorServerMs, 0, 1e14)
  if (epochSeq === null || anchorPosMs === null || anchorServerMs === null || typeof obj.playing !== 'boolean') {
    return null
  }
  const trackUid = obj.trackUid === null ? null : cleanStr(obj.trackUid, 64)
  if (obj.trackUid !== null && !trackUid) return null
  if (obj.hostAdPaused !== undefined && typeof obj.hostAdPaused !== 'boolean') return null
  return {
    epochSeq,
    trackUid,
    playing: obj.playing,
    anchorPosMs,
    anchorServerMs,
    ...(obj.hostAdPaused !== undefined ? { hostAdPaused: obj.hostAdPaused } : {}),
  }
}

function parseEnrichPatch(raw: unknown): TrackEnrichPatch | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  const uid = cleanStr(obj.uid, 64) ?? undefined
  const isrc = normalizeIsrc(obj.isrc)
  const ids = obj.ids !== undefined ? normalizePlatformIds(obj.ids) : undefined
  const durationMs =
    obj.durationMs !== undefined ? (finiteInt(obj.durationMs, 1, 86_400_000) ?? undefined) : undefined
  const coverUrl = obj.coverUrl !== undefined ? sanitizeHttpsUrl(obj.coverUrl, COVER_DOMAINS) : undefined
  const previewUrl =
    obj.previewUrl !== undefined ? sanitizeHttpsUrl(obj.previewUrl, PREVIEW_AUDIO_DOMAINS) : undefined
  const mediaOffsetMs =
    obj.mediaOffsetMs !== undefined ? (finiteInt(obj.mediaOffsetMs, -300_000, 300_000) ?? undefined) : undefined
  if (
    !isrc &&
    (!ids || Object.keys(ids).length === 0) &&
    durationMs === undefined &&
    !coverUrl &&
    !previewUrl &&
    mediaOffsetMs === undefined
  ) {
    return null
  }
  return {
    ...(uid ? { uid } : {}),
    ...(isrc ? { isrc } : {}),
    ...(ids && Object.keys(ids).length > 0 ? { ids } : {}),
    ...(durationMs !== undefined ? { durationMs } : {}),
    ...(coverUrl ? { coverUrl } : {}),
    ...(previewUrl ? { previewUrl } : {}),
    ...(mediaOffsetMs !== undefined ? { mediaOffsetMs } : {}),
  }
}

function parseArray<T>(raw: unknown, maxLen: number, parser: (item: unknown) => T | null): T[] | null {
  if (!Array.isArray(raw) || raw.length > maxLen) return null
  const out: T[] = []
  for (const item of raw) {
    const parsed = parser(item)
    if (!parsed) return null
    out.push(parsed)
  }
  return out
}

function parseRoomState(raw: unknown): RoomState | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  if (typeof obj.code !== 'string' || !isRoomCode(obj.code)) return null
  const hostCid = cleanStr(obj.hostCid, 64)
  if (!hostCid || typeof obj.allowGuestControl !== 'boolean' || typeof obj.allowGuestAdd !== 'boolean') {
    return null
  }
  const participants = parseArray(obj.participants, MAX_PARTICIPANTS, parseParticipant)
  const queue = parseArray(obj.queue, MAX_QUEUE_TRACKS, parseTrack)
  const queueRev = finiteInt(obj.queueRev, 0, 1e12)
  const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
  const anchor = parseAnchor(obj.anchor)
  if (!participants || !queue || queueRev === null || currentIndex === null || !anchor) return null
  return {
    code: normalizeCode(obj.code),
    hostCid,
    allowGuestControl: obj.allowGuestControl,
    allowGuestAdd: obj.allowGuestAdd,
    participants,
    queue,
    queueRev,
    currentIndex,
    anchor,
  }
}

function parseQueuePatchOp(raw: unknown): QueuePatchOp | null {
  if (!raw || typeof raw !== 'object') return null
  const obj = raw as Record<string, unknown>
  switch (obj.kind) {
    case 'add': {
      if (obj.insert !== 'next' && obj.insert !== 'last') return null
      const tracks = parseArray(obj.tracks, MAX_BATCH_ADD, parseTrack)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (!tracks || tracks.length === 0 || currentIndex === null) return null
      return { kind: 'add', insert: obj.insert, tracks, currentIndex }
    }
    case 'remove': {
      const uid = cleanStr(obj.uid, 64)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (!uid || currentIndex === null) return null
      return { kind: 'remove', uid, currentIndex }
    }
    case 'move': {
      const fromIndex = finiteInt(obj.fromIndex, 0, MAX_QUEUE_TRACKS)
      const toIndex = finiteInt(obj.toIndex, 0, MAX_QUEUE_TRACKS)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (fromIndex === null || toIndex === null || currentIndex === null) return null
      return { kind: 'move', fromIndex, toIndex, currentIndex }
    }
    case 'clear': {
      const currentIndex = finiteInt(obj.currentIndex, -1, 0)
      if (currentIndex === null) return null
      return { kind: 'clear', currentIndex }
    }
    case 'select': {
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (currentIndex === null) return null
      return { kind: 'select', currentIndex }
    }
    case 'replace': {
      const queue = parseArray(obj.queue, MAX_QUEUE_TRACKS, parseTrack)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (!queue || currentIndex === null) return null
      return { kind: 'replace', queue, currentIndex }
    }
    default:
      return null
  }
}

function parseJsonObject(raw: string): Record<string, unknown> | null {
  if (typeof raw !== 'string' || raw.length > 262_144) return null
  try {
    const parsed: unknown = JSON.parse(raw)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null
    const obj = parsed as Record<string, unknown>
    if (obj.v !== PROTOCOL_VERSION || typeof obj.t !== 'string') return null
    return obj
  } catch {
    return null
  }
}

export function decodeClientMsg(raw: string): ClientMsg | null {
  const obj = parseJsonObject(raw)
  if (!obj) return null

  switch (obj.t) {
    case 'clock.ping': {
      const seq = finiteInt(obj.seq, 0, 1e12)
      const t0 = finiteNum(obj.t0, 0, 1e14)
      if (seq === null || t0 === null) return null
      return { v: 3, t: 'clock.ping', seq, t0 }
    }
    case 'standby.open': {
      const profile = parseProfile(obj.profile)
      if (
        !profile ||
        typeof obj.syncProfile !== 'string' ||
        !VALID_SYNC_PROFILES.has(obj.syncProfile as SyncProfile)
      ) {
        return null
      }
      const track = obj.track === null ? null : parseTrackInput(obj.track)
      if (obj.track !== null && !track) return null
      return {
        v: 3,
        t: 'standby.open',
        profile,
        syncProfile: obj.syncProfile as SyncProfile,
        track,
      }
    }
    case 'standby.update': {
      const track = obj.track === null ? null : parseTrackInput(obj.track)
      if (obj.track !== null && !track) return null
      return { v: 3, t: 'standby.update', track }
    }
    case 'standby.close':
      return { v: 3, t: 'standby.close' }
    case 'room.create': {
      const profile = parseProfile(obj.profile)
      if (
        !profile ||
        typeof obj.syncProfile !== 'string' ||
        !VALID_SYNC_PROFILES.has(obj.syncProfile as SyncProfile) ||
        typeof obj.allowGuestControl !== 'boolean'
      ) {
        return null
      }
      if (
        obj.audioMode !== undefined &&
        (typeof obj.audioMode !== 'string' || !VALID_AUDIO_MODES.has(obj.audioMode as AudioMode))
      ) {
        return null
      }
      if (obj.allowGuestAdd !== undefined && typeof obj.allowGuestAdd !== 'boolean') return null
      const queue = parseArray(obj.queue, MAX_QUEUE_TRACKS, parseTrackInput)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      const anchor = parseAnchor(obj.anchor)
      if (!queue || currentIndex === null || !anchor) return null
      const hostToken = cleanStr(obj.hostToken, 128) ?? undefined
      const code = typeof obj.code === 'string' && isRoomCode(obj.code) ? normalizeCode(obj.code) : undefined
      return {
        v: 3,
        t: 'room.create',
        profile,
        syncProfile: obj.syncProfile as SyncProfile,
        ...(obj.audioMode ? { audioMode: obj.audioMode as AudioMode } : {}),
        allowGuestControl: obj.allowGuestControl,
        ...(obj.allowGuestAdd !== undefined ? { allowGuestAdd: obj.allowGuestAdd } : {}),
        queue,
        currentIndex,
        anchor,
        ...(hostToken ? { hostToken } : {}),
        ...(code ? { code } : {}),
      }
    }
    case 'room.join': {
      if (typeof obj.code !== 'string' || !isRoomCode(obj.code)) return null
      const profile = parseProfile(obj.profile)
      if (
        !profile ||
        typeof obj.syncProfile !== 'string' ||
        !VALID_SYNC_PROFILES.has(obj.syncProfile as SyncProfile) ||
        typeof obj.audioMode !== 'string' ||
        !VALID_AUDIO_MODES.has(obj.audioMode as AudioMode)
      ) {
        return null
      }
      return {
        v: 3,
        t: 'room.join',
        code: normalizeCode(obj.code),
        profile,
        syncProfile: obj.syncProfile as SyncProfile,
        audioMode: obj.audioMode as AudioMode,
      }
    }
    case 'room.leave':
    case 'room.end':
    case 'room.kickAll':
    case 'queue.clear':
      return { v: 3, t: obj.t }
    case 'room.kick': {
      const targetCid = cleanStr(obj.targetCid, 64)
      if (!targetCid) return null
      return { v: 3, t: 'room.kick', targetCid }
    }
    case 'room.permissions': {
      if (obj.allowGuestControl !== undefined && typeof obj.allowGuestControl !== 'boolean') return null
      if (obj.allowGuestAdd !== undefined && typeof obj.allowGuestAdd !== 'boolean') return null
      if (obj.allowGuestControl === undefined && obj.allowGuestAdd === undefined) return null
      return {
        v: 3,
        t: 'room.permissions',
        ...(obj.allowGuestControl !== undefined ? { allowGuestControl: obj.allowGuestControl } : {}),
        ...(obj.allowGuestAdd !== undefined ? { allowGuestAdd: obj.allowGuestAdd } : {}),
      }
    }
    case 'room.memberPermission': {
      const targetCid = cleanStr(obj.targetCid, 64)
      if (!targetCid || typeof obj.canAddTracks !== 'boolean') return null
      return { v: 3, t: 'room.memberPermission', targetCid, canAddTracks: obj.canAddTracks }
    }
    case 'room.mode': {
      if (typeof obj.audioMode !== 'string' || !VALID_AUDIO_MODES.has(obj.audioMode as AudioMode)) {
        return null
      }
      if (
        obj.syncProfile !== undefined &&
        (typeof obj.syncProfile !== 'string' || !VALID_SYNC_PROFILES.has(obj.syncProfile as SyncProfile))
      ) {
        return null
      }
      return {
        v: 3,
        t: 'room.mode',
        audioMode: obj.audioMode as AudioMode,
        ...(obj.syncProfile ? { syncProfile: obj.syncProfile as SyncProfile } : {}),
      }
    }
    case 'profile.update': {
      const name = obj.name !== undefined ? (cleanStr(obj.name, 48) ?? undefined) : undefined
      const avatarUrl =
        obj.avatarUrl === null
          ? null
          : obj.avatarUrl !== undefined
            ? sanitizeHttpsUrl(obj.avatarUrl, COVER_DOMAINS)
            : undefined
      const platform =
        typeof obj.platform === 'string' && VALID_PLATFORMS.has(obj.platform as PlatformId)
          ? (obj.platform as PlatformId)
          : undefined
      const profileUrl = obj.profileUrl !== undefined ? sanitizeHttpsUrl(obj.profileUrl) : undefined
      if (name === undefined && avatarUrl === undefined && platform === undefined && profileUrl === undefined) {
        return null
      }
      return {
        v: 3,
        t: 'profile.update',
        ...(name !== undefined ? { name } : {}),
        ...(avatarUrl !== undefined ? { avatarUrl } : {}),
        ...(platform !== undefined ? { platform } : {}),
        ...(profileUrl !== undefined ? { profileUrl } : {}),
      }
    }
    case 'anchor.update': {
      const anchor = parseAnchor(obj.anchor)
      if (!anchor) return null
      return { v: 3, t: 'anchor.update', anchor }
    }
    case 'queue.add': {
      if (obj.insert !== 'next' && obj.insert !== 'last') return null
      const tracks = parseArray(obj.tracks, MAX_BATCH_ADD, parseTrackInput)
      if (!tracks || tracks.length === 0) return null
      return { v: 3, t: 'queue.add', insert: obj.insert, tracks }
    }
    case 'queue.remove': {
      const uid = cleanStr(obj.uid, 64)
      if (!uid) return null
      return { v: 3, t: 'queue.remove', uid }
    }
    case 'queue.move': {
      const fromIndex = finiteInt(obj.fromIndex, 0, MAX_QUEUE_TRACKS)
      const toIndex = finiteInt(obj.toIndex, 0, MAX_QUEUE_TRACKS)
      if (fromIndex === null || toIndex === null) return null
      return { v: 3, t: 'queue.move', fromIndex, toIndex }
    }
    case 'queue.select': {
      const index = finiteInt(obj.index, 0, MAX_QUEUE_TRACKS)
      if (index === null) return null
      return { v: 3, t: 'queue.select', index }
    }
    case 'queue.replace': {
      const queue = parseArray(obj.queue, MAX_QUEUE_TRACKS, parseTrackInput)
      const currentIndex = finiteInt(obj.currentIndex, -1, MAX_QUEUE_TRACKS)
      if (!queue || currentIndex === null) return null
      return { v: 3, t: 'queue.replace', queue, currentIndex }
    }
    case 'track.enrich': {
      const patch = parseEnrichPatch(obj.patch)
      if (!patch) return null
      return { v: 3, t: 'track.enrich', patch }
    }
    case 'peer.telemetry': {
      const telemetry = parseTelemetry(obj.telemetry)
      if (!telemetry) return null
      return { v: 3, t: 'peer.telemetry', telemetry }
    }
    case 'playback.control': {
      if (typeof obj.action !== 'string' || !VALID_ACTIONS.has(obj.action as ControlAction)) {
        return null
      }
      const posMs = obj.posMs === undefined ? undefined : finiteNum(obj.posMs, 0, 86_400_000)
      if (posMs === null) return null
      return {
        v: 3,
        t: 'playback.control',
        action: obj.action as ControlAction,
        ...(posMs !== undefined ? { posMs } : {}),
      }
    }
    default:
      return null
  }
}

export function decodeServerMsg(raw: string): ServerMsg | null {
  const obj = parseJsonObject(raw)
  if (!obj) return null

  switch (obj.t) {
    case 'welcome': {
      const cid = cleanStr(obj.cid, 64)
      const serverTs = finiteNum(obj.serverTs, 0, 1e14)
      if (!cid || serverTs === null) return null
      return { v: 3, t: 'welcome', cid, serverTs }
    }
    case 'clock.pong': {
      const seq = finiteInt(obj.seq, 0, 1e12)
      const t0 = finiteNum(obj.t0, 0, 1e14)
      const t1 = finiteNum(obj.t1, 0, 1e14)
      const t2 = finiteNum(obj.t2, 0, 1e14)
      if (seq === null || t0 === null || t1 === null || t2 === null) return null
      return { v: 3, t: 'clock.pong', seq, t0, t1, t2 }
    }
    case 'standby.ready': {
      const standbyId = cleanStr(obj.standbyId, 64)
      if (!standbyId || !isStandbyToken(standbyId) || typeof obj.code !== 'string' || !isRoomCode(obj.code)) {
        return null
      }
      return { v: 3, t: 'standby.ready', standbyId, code: normalizeCode(obj.code) }
    }
    case 'standby.promoted': {
      const state = parseRoomState(obj.state)
      const hostToken = cleanStr(obj.hostToken, 128)
      if (!state || !hostToken) return null
      return { v: 3, t: 'standby.promoted', state, hostToken }
    }
    case 'room.joined': {
      if (obj.role !== 'host' && obj.role !== 'guest') return null
      const state = parseRoomState(obj.state)
      if (!state) return null
      const hostToken = cleanStr(obj.hostToken, 128) ?? undefined
      return { v: 3, t: 'room.joined', role: obj.role, state, ...(hostToken ? { hostToken } : {}) }
    }
    case 'room.state': {
      const state = parseRoomState(obj.state)
      if (!state) return null
      return { v: 3, t: 'room.state', state }
    }
    case 'room.ended': {
      if (typeof obj.reason !== 'string' || !VALID_END_REASONS.has(obj.reason as Extract<ServerMsg, { t: 'room.ended' }>['reason'])) {
        return null
      }
      return {
        v: 3,
        t: 'room.ended',
        reason: obj.reason as Extract<ServerMsg, { t: 'room.ended' }>['reason'],
      }
    }
    case 'anchor.broadcast': {
      const anchor = parseAnchor(obj.anchor)
      if (!anchor) return null
      return { v: 3, t: 'anchor.broadcast', anchor }
    }
    case 'queue.patch': {
      const rev = finiteInt(obj.rev, 0, 1e12)
      const op = parseQueuePatchOp(obj.op)
      if (rev === null || !op) return null
      return { v: 3, t: 'queue.patch', rev, op }
    }
    case 'track.updated': {
      const track = parseTrack(obj.track)
      if (!track) return null
      return { v: 3, t: 'track.updated', track }
    }
    case 'peer.telemetry.broadcast': {
      const cid = cleanStr(obj.cid, 64)
      const telemetry = parseTelemetry(obj.telemetry)
      if (!cid || !telemetry) return null
      return { v: 3, t: 'peer.telemetry.broadcast', cid, telemetry }
    }
    case 'command.execute': {
      if (typeof obj.action !== 'string' || !VALID_ACTIONS.has(obj.action as ControlAction)) {
        return null
      }
      const fromCid = cleanStr(obj.fromCid, 64)
      if (!fromCid) return null
      const posMs = obj.posMs === undefined ? undefined : finiteNum(obj.posMs, 0, 86_400_000)
      if (posMs === null) return null
      return {
        v: 3,
        t: 'command.execute',
        action: obj.action as ControlAction,
        ...(posMs !== undefined ? { posMs } : {}),
        fromCid,
      }
    }
    case 'error': {
      const code = cleanStr(obj.code, 64)
      const message = cleanStr(obj.message, 256)
      if (!code || !message) return null
      return { v: 3, t: 'error', code, message }
    }
    default:
      return null
  }
}

export function encodeMsg(msg: ClientMsg | ServerMsg): string {
  return JSON.stringify(msg)
}
