import type { PlaybackAnchor } from '@everything-jam/protocol'
import { clamp } from './clock.js'

export function clampManualTrimMs(rawMs: number): number {
  if (!Number.isFinite(rawMs)) return 0
  const snapped = Math.round(rawMs / 5) * 5
  return clamp(snapped, -500, 500)
}

export async function probeOutputLatencyMs(): Promise<number> {
  if (typeof globalThis === 'undefined' || !('AudioContext' in globalThis)) {
    return 0
  }
  type MaybeAudioContext = {
    outputLatency?: number
    close?: () => Promise<void> | void
  }
  type AudioContextCtor = new (opts?: { latencyHint?: 'interactive' | 'balanced' | 'playback' }) => MaybeAudioContext
  const Ctor = (globalThis as unknown as { AudioContext?: AudioContextCtor }).AudioContext
  if (!Ctor) return 0

  let ctx: MaybeAudioContext | null = null
  try {
    ctx = new Ctor({ latencyHint: 'interactive' })
    const raw = typeof ctx.outputLatency === 'number' && Number.isFinite(ctx.outputLatency) ? ctx.outputLatency : 0
    return clamp(Math.round(raw * 1000), 0, 1000)
  } catch {
    return 0
  } finally {
    try {
      await ctx?.close?.()
    } catch {
      // Ignore closed AudioContext errors
    }
  }
}

export function buildHostAnchor(opts: {
  epochSeq: number
  trackUid: string | null
  playing: boolean
  enginePosMs: number
  hostOutputLatencyMs: number
  hostServerNowMs: number
  hostAdPaused?: boolean
}): PlaybackAnchor {
  const acousticPosMs = Math.max(0, opts.enginePosMs - opts.hostOutputLatencyMs)
  return {
    epochSeq: Math.max(0, Math.trunc(opts.epochSeq)),
    trackUid: opts.trackUid,
    playing: opts.playing,
    anchorPosMs: Math.round(acousticPosMs * 100) / 100,
    anchorServerMs: Math.round(opts.hostServerNowMs * 100) / 100,
    ...(opts.hostAdPaused ? { hostAdPaused: true } : {}),
  }
}

export function computeExpectedEnginePosMs(opts: {
  anchor: PlaybackAnchor
  guestServerNowMs: number
  guestOutputLatencyMs: number
  mediaOffsetMs?: number
  trackDurationMs?: number
}): number {
  const { anchor } = opts
  const elapsedMs =
    anchor.playing && !anchor.hostAdPaused
      ? Math.max(0, opts.guestServerNowMs - anchor.anchorServerMs)
      : 0
  const roomAcousticMs = anchor.anchorPosMs + elapsedMs
  const targetEngineMs = roomAcousticMs + opts.guestOutputLatencyMs + (opts.mediaOffsetMs ?? 0)
  const duration = opts.trackDurationMs ?? 0
  if (duration > 0) {
    return clamp(targetEngineMs, 0, duration)
  }
  return Math.max(0, targetEngineMs)
}
