import { Tracer, type LunaUnload } from '@luna/core'
import { PlayState, StyleTag } from '@luna/lib'
import { buildTrustedHubOrigins, type AudioMode, type RoomState, type SyncProfile } from '@everything-jam/protocol'
import styles from 'file://ui/styles.css?minify'
import { DiscordPresenceController } from './discord/presence'
import { SessionClient } from './session/client'
import { normalizeServerUrl } from './session/settings'
import { hydrateLocalIdentity, localProfile } from './tidal/identity'
import { ensureQueueInStore, findMissingMetadataUpdates } from './tidal/metadata'
import { TidalPlaybackBridge, detectTidalEngine } from './tidal/playback'
import { TidalQueueSync } from './tidal/queueSync'
import { storage } from './tidal/storage'
import { FooterButtonMount } from './ui/footerButton'
import { unmountParticipantMenu } from './ui/participantMenu'
import { PopoverController } from './ui/popover'
import { QueueAvatarDecorator } from './ui/queueAvatars'
import { QueueHeaderMount } from './ui/queueHeader'
import { LunaJamSettingsView } from './ui/settings'
import { showToast, unmountToast } from './ui/toast'

export const unloads = new Set<LunaUnload>()
export const { errSignal } = Tracer('lunajam')
export const Settings = LunaJamSettingsView

new StyleTag('LunaJam', unloads, styles)

const session = new SessionClient()
const attemptedMeta = new Set<string>()
let lastRoomCode: string | null = null
let lastParticipantCount = 0
let lastAppliedQueueKey = ''
let lastPreloadedKey = ''
let lastSentProfileKey = ''

function queueKey(room: RoomState): string {
  return `${room.queueRev}:${room.currentIndex}:${room.queue
    .map((t) => `${t.uid}:${t.ids.tidal ?? ''}:${t.isrc ?? ''}`)
    .join(',')}`
}

function waitIdentityBudget(): Promise<unknown> {
  return Promise.race([
    hydrateLocalIdentity(),
    new Promise<void>((resolve) => setTimeout(resolve, 800)),
  ])
}

async function syncIdentityToSession(): Promise<void> {
  await hydrateLocalIdentity()
  const snap = session.snapshot()
  if (!snap.room && !snap.standbyId) return
  const profile = localProfile(snap.cid ?? '')
  const key = `${profile.name}|${profile.avatarUrl ?? ''}|${profile.platform}|${profile.profileUrl ?? ''}`
  if (key === lastSentProfileKey) return
  lastSentProfileKey = key
  session.updateProfile(profile)
}

async function startJam(seedTrackIds?: string[]): Promise<void> {
  await waitIdentityBudget()
  const cfg = storage.get()
  const profile = localProfile(session.snapshot().cid ?? '')
  const engine = detectTidalEngine()
  const seed = await queueSync.snapshotSeedQueue()
  let queue = seed.queue
  let currentIndex = seed.currentIndex

  if (seedTrackIds && seedTrackIds.length > 0) {
    const inputs = await queueSync.snapshotInputsFromTrackIds(seedTrackIds)
    const seeded = inputs.map((t, i) => ({
      ...t,
      uid: `ctx-${Date.now()}-${i}`,
    }))
    queue = [...seeded, ...queue]
    currentIndex = 0
  }

  if (queue.length === 0) {
    const rawNow = PlayState.playbackContext?.actualProductId
    const nowId = rawNow !== undefined && rawNow !== null && String(rawNow) !== '' ? String(rawNow) : null
    if (nowId) {
      const inputs = await queueSync.snapshotInputsFromTrackIds([nowId])
      if (inputs[0]) {
        queue = [{ ...inputs[0], uid: `now-${Date.now()}` }]
        currentIndex = 0
      }
    }
  }

  const baseAnchor = playback.readCurrentHostAnchor(undefined, true)
  const activeTrackUid = currentIndex >= 0 ? (queue[currentIndex]?.uid ?? null) : null

  session.createRoom({
    serverUrl: cfg.serverUrl,
    profile,
    syncProfile: engine.profile,
    allowGuestControl: cfg.defaultAllowGuestControl,
    allowGuestAdd: cfg.defaultAllowGuestAdd,
    queue,
    currentIndex,
    anchor: {
      ...baseAnchor,
      trackUid: activeTrackUid,
    },
  })
}

async function joinJam(input: string, audioMode: AudioMode, serverUrl?: string): Promise<void> {
  await waitIdentityBudget()
  const cfg = storage.get()
  const trusted = buildTrustedHubOrigins(normalizeServerUrl(cfg.serverUrl))
  if (serverUrl !== undefined && !trusted.has(normalizeServerUrl(serverUrl))) {
    showToast('Invite link points to an untrusted Jam server. Change Relay URL in Settings first.', 'warn')
    return
  }
  const engine = detectTidalEngine()
  const syncProfile: SyncProfile = audioMode === 'speaker' ? 'passive' : engine.profile
  const ok = await session.joinRoom({
    input,
    serverUrl: serverUrl ?? cfg.serverUrl,
    profile: localProfile(session.snapshot().cid ?? ''),
    syncProfile,
    audioMode,
  })
  if (!ok) {
    const err = session.snapshot().error
    if (err) showToast(err, 'warn')
  }
}

function selectRoomIndex(index: number): void {
  const s = session.snapshot()
  if (!s.room || index < 0 || index >= s.room.queue.length) return
  if (s.role === 'host' || s.room.allowGuestControl) {
    session.selectQueueIndex(index)
  } else {
    showToast('Host restricted queue controls', 'warn')
  }
}

const queueSync = new TidalQueueSync(unloads, {
  isActive: () => Boolean(session.snapshot().room),
  getRole: () => session.snapshot().role,
  canGuestEdit: () => Boolean(session.snapshot().room?.allowGuestControl),
  canGuestAdd: () => {
    const s = session.snapshot()
    if (s.role === 'host') return true
    if (!s.room) return false
    const me = s.cid ? s.room.participants.find((p) => p.cid === s.cid) : undefined
    return me ? me.canAddTracks : s.room.allowGuestAdd
  },
  getLocalProfile: () => localProfile(session.snapshot().cid ?? ''),
  getRoom: () => session.snapshot().room,
  onGuestAdd: async (trackIds, insert) => {
    const inputs = await queueSync.snapshotInputsFromTrackIds(trackIds)
    session.addTracks(inputs, insert)
    showToast(inputs.length > 1 ? `Added ${inputs.length} tracks to Jam` : 'Added to Jam')
  },
  onGuestMove: (fromIndex, toIndex) => session.moveTrack(fromIndex, toIndex),
  onGuestRemove: (roomUid) => session.removeTrack(roomUid),
  onGuestSelectIndex: (roomIndex) => selectRoomIndex(roomIndex),
  onHostReplaceQueue: (queue, currentIndex) => session.replaceQueue(queue, currentIndex),
  onHostQueueReconciled: () => playback.emitHostAnchor(),
  onEnrichTrack: (patch) => session.enrichTrack(patch),
  onUnresolvableTrack: (track) => showToast(`Unavailable on TIDAL: ${track.title}`, 'warn'),
  onStartJamWithTracks: (trackIds) => {
    void startJam(trackIds)
  },
  onRestricted: () => showToast('Host restricted queue controls', 'warn'),
  onAddRestricted: () => showToast('Host turned off track additions for you', 'warn'),
})

const playback = new TidalPlaybackBridge(unloads, {
  isActive: () => Boolean(session.snapshot().room),
  getRole: () => session.snapshot().role,
  getAudioMode: () => session.snapshot().audioMode,
  canGuestControl: () => Boolean(session.snapshot().room?.allowGuestControl),
  getClock: () => session.clock,
  getCurrentAnchor: () => session.snapshot().room?.anchor ?? null,
  getCurrentQueue: () => session.snapshot().room?.queue ?? [],
  getCurrentIndex: () => session.snapshot().room?.currentIndex ?? -1,
  getTidalIdForTrack: (track) => queueSync.getTidalIdForTrack(track),
  getQueueIndexByUid: (uid) => session.snapshot().room?.queue.findIndex((t) => t.uid === uid) ?? -1,
  onHostBroadcastAnchor: (anchor) => session.sendAnchor(anchor),
  onHostSelectIndex: (index) => session.selectQueueIndex(index),
  onGuestControl: (action, posMs) => session.sendControl(action, posMs),
  onPreResolveNext: (nextIndex) => {
    const next = session.snapshot().room?.queue[nextIndex]
    if (!next) return
    void queueSync.resolveMissingTrack(next).then((id) => {
      if (id) void ensureQueueInStore([id], id)
    })
  },
  onTelemetry: (telemetry, localDriftMs) => {
    session.setLocalDriftMs(localDriftMs)
    session.sendTelemetry(telemetry)
  },
  onRestricted: () => showToast('Host restricted playback controls', 'warn'),
})

const queueHeader = new QueueHeaderMount(unloads, session, selectRoomIndex)

const queueAvatars = new QueueAvatarDecorator(unloads, session, queueSync)

const popover = new PopoverController({
  session,
  onStartJam: () => {
    void startJam()
  },
  onJoinJam: (input, mode) => {
    void joinJam(input, mode)
  },
  onSelectTrack: selectRoomIndex,
})

new FooterButtonMount(unloads, session, popover, queueHeader)

new DiscordPresenceController(unloads, session, {
  onJoinLink: (code, serverUrl) => {
    showToast('Joining Jam from link')
    void joinJam(code, storage.get().defaultGuestAudioMode, serverUrl)
  },
})

unloads.add(
  session.onCommand((action, posMs) => {
    playback.executeHostCommand(action, posMs)
  }),
)

unloads.add(
  session.onAnchor(() => {
    playback.onAnchorReceived()
  }),
)

unloads.add(
  session.onPromoted((room) => {
    showToast(`Started Jam ${room.code} from Discord`)
  }),
)

unloads.add(
  session.subscribe((state) => {
    const room = state.room
    if (!room) {
      if (lastRoomCode !== null) {
        lastRoomCode = null
        lastParticipantCount = 0
        lastAppliedQueueKey = ''
        lastPreloadedKey = ''
        attemptedMeta.clear()
        queueSync.clearMappings()
        playback.resetSync()
        queueAvatars.refresh()
        if (state.endReason === 'banned') showToast('You were banned from this Jam', 'warn')
        else if (state.endReason === 'kicked_all') showToast('Removed from Jam', 'warn')
        else if (
          state.endReason === 'host_ended' ||
          state.endReason === 'host_left' ||
          state.endReason === 'expired'
        ) {
          showToast('Jam ended')
        }
      }
      return
    }

    if (lastRoomCode === null) {
      lastRoomCode = room.code
      lastParticipantCount = room.participants.length
    } else if (room.participants.length > lastParticipantCount) {
      const joined = room.participants[room.participants.length - 1]
      if (joined && joined.cid !== state.cid) showToast(`${joined.name} joined`)
      lastParticipantCount = room.participants.length
    } else {
      lastParticipantCount = room.participants.length
    }

    const key = queueKey(room)
    if (key !== lastAppliedQueueKey) {
      lastAppliedQueueKey = key
      queueSync.applyRoomToNative(room)
    }

    if (state.role === 'host') {
      const activeUid = room.currentIndex >= 0 ? (room.queue[room.currentIndex]?.uid ?? null) : null
      if (activeUid !== room.anchor.trackUid) {
        session.sendAnchor(playback.readCurrentHostAnchor(0, true))
      }
    } else if (state.role === 'guest') {
      playback.tickGuestSync()
    }

    queueAvatars.refresh()

    const activeTrack = room.currentIndex >= 0 ? room.queue[room.currentIndex] : undefined
    const resolvedIds = room.queue
      .map((t) => queueSync.getTidalIdForTrack(t))
      .filter((id): id is string => Boolean(id))
    const activeTidalId = queueSync.getTidalIdForTrack(activeTrack)
    const preloadKey = `${key}|${activeTidalId ?? ''}`
    if (preloadKey === lastPreloadedKey) return
    lastPreloadedKey = preloadKey

    ensureQueueInStore(resolvedIds, activeTidalId)
      .then((loadedNew) => {
        if (!loadedNew) return
        const latest = session.snapshot()
        if (!latest.room || latest.room.code !== room.code) return
        queueSync.applyRoomToNative(latest.room)
        if (latest.role === 'guest') playback.tickGuestSync()
        queueAvatars.refresh()
      })
      .catch(() => {})

    findMissingMetadataUpdates(room.queue, attemptedMeta)
      .then((patches) => {
        for (const patch of patches) session.enrichTrack(patch)
      })
      .catch(() => {})
  }),
)

const t1 = setTimeout(() => {
  void syncIdentityToSession()
}, 300)
const t2 = setTimeout(() => {
  void syncIdentityToSession()
}, 2500)

unloads.add(() => {
  clearTimeout(t1)
  clearTimeout(t2)
  popover.unmount()
  unmountParticipantMenu()
  unmountToast()
  queueSync.clearMappings()
  session.dispose()
})
