import {
  DEFAULT_HUB_URL,
  LEGACY_LUNAJAM_URL,
  normalizeHubUrl,
  type AudioMode,
} from '@everything-jam/protocol'
import { clampManualTrimMs } from '@everything-jam/sync-engine'

export interface LunaJamSettings {
  serverUrl: string
  defaultAllowGuestControl: boolean
  defaultAllowGuestAdd: boolean
  defaultGuestAudioMode: AudioMode
  manualTrimMs: number
  deviceTrims: Record<string, number>
  discordRpcEnabled: boolean
  discordListenTogether: boolean
  discordShowPaused: boolean
  discordClientId: string
  peerId: string
}

export const DEFAULT_DISCORD_CLIENT_ID = '1130698654987067493'

export function generatePeerId(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-'
  const bytes = new Uint8Array(24)
  if (typeof globalThis.crypto?.getRandomValues === 'function') {
    globalThis.crypto.getRandomValues(bytes)
  } else {
    for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256)
  }
  let out = ''
  for (let i = 0; i < bytes.length; i++) out += chars[bytes[i]! % chars.length]
  return out
}

export const defaultSettings: LunaJamSettings = {
  serverUrl: DEFAULT_HUB_URL,
  defaultAllowGuestControl: true,
  defaultAllowGuestAdd: true,
  defaultGuestAudioMode: 'synced',
  manualTrimMs: 0,
  deviceTrims: {},
  discordRpcEnabled: true,
  discordListenTogether: true,
  discordShowPaused: true,
  discordClientId: DEFAULT_DISCORD_CLIENT_ID,
  peerId: generatePeerId(),
}

export function normalizeServerUrl(raw: string): string {
  const clean = normalizeHubUrl(raw)
  if (clean === LEGACY_LUNAJAM_URL || clean === 'http://lunajam.sn0w13.de') {
    return DEFAULT_HUB_URL
  }
  return clean
}

export function normalizeAudioMode(raw: unknown): AudioMode {
  if (raw === 'speaker') return 'speaker'
  if (raw === 'synced' || raw === 'remote') return 'synced'
  return 'synced'
}

export function normalizeTrimMs(raw: unknown): number {
  return typeof raw === 'number' ? clampManualTrimMs(raw) : 0
}

export function wsUrlFromServer(serverUrl: string): string {
  const clean = normalizeServerUrl(serverUrl)
  return `${clean.replace(/^http:/, 'ws:').replace(/^https:/, 'wss:')}/ws`
}

export function validateDiscordClientId(raw: string): string {
  const trimmed = raw.trim()
  return /^\d{17,22}$/.test(trimmed) ? trimmed : DEFAULT_DISCORD_CLIENT_ID
}
